/* DAWAH X — ahmad, অধ্যায় 79 · খণ্ড 79 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][79]=[[15601,15601,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏النُّعْمَانُ بْنُ سَالِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ أَوْسٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي رَزِينٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ أَبِي شَيْخٌ كَبِيرٌ لَا يَسْتَطِيعُ الْحَجَّ وَالْعُمْرَةَ وَلَا ‏ ‏الظَّعْنَ ‏ ‏قَالَ ‏ ‏حُجَّ عَنْ أَبِيكَ وَاعْتَمِرْ ‏","","",""],[15602,15602,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ لَقِيطٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏رَفَعَهُ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُؤْيَا الْمُؤْمِنِ جُزْءٌ مِنْ أَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ ‏ ‏أَشُكُّ أَنَّهُ قَالَ رُؤْيَا الْمُؤْمِنِ عَلَى رِجْلِ طَائِرٍ مَا لَمْ يُخْبِرْ بِهَا فَإِذَا أَخْبَرَ بِهَا وَقَعَتْ ‏","","",""],[15603,15603,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ حُدَسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ الْعُقَيْلِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏أَكُلُّنَا يَرَى رَبَّهُ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ وَمَا آيَةُ ذَلِكَ فِي خَلْقِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَيْسَ كُلُّكُمْ يَنْظُرُ إِلَى الْقَمَرِ مُخْلِيًا بِهِ قَالَ بَلَى قَالَ فَاللَّهُ أَعْظَمُ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ يُحْيِي اللَّهُ الْمَوْتَى وَمَا آيَةُ ذَلِكَ فِي خَلْقِهِ قَالَ أَمَا مَرَرْتَ بِوَادِي أَهْلِكَ ‏ ‏مَحْلًا ‏ ‏قَالَ بَلَى قَالَ أَمَا مَرَرْتَ بِهِ يَهْتَزُّ خَضِرًا قَالَ قُلْتُ بَلَى قَالَ ثُمَّ مَرَرْتَ بِهِ ‏ ‏مَحْلًا ‏ ‏قَالَ بَلَى قَالَ فَكَذَلِكَ يُحْيِي اللَّهُ الْمَوْتَى وَذَلِكَ آيَتُهُ فِي خَلْقِهِ ‏","","",""],[15604,15604,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ حُدُسٍ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ يُحْيِي اللَّهُ الْمَوْتَى فَقَالَ ‏ ‏أَمَا مَرَرْتَ بِالْوَادِي ‏ ‏مُمْحِلًا ‏ ‏ثُمَّ تَمُرُّ بِهِ خَضِرًا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قَالَهُ أَكْثَرَ مِنْ مَرَّتَيْنِ ‏ ‏كَذَلِكَ يُحْيِي اللَّهُ الْمَوْتَى ‏","","",""],[15605,15605,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ الْعُقَيْلِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ يُحْيِي اللَّهُ الْمَوْتَى قَالَ ‏ ‏أَمَا مَرَرْتَ بِأَرْضٍ مِنْ أَرْضِكَ مُجْدِبَةٍ ثُمَّ مَرَرْتَ بِهَا مُخْصَبَةً قَالَ نَعَمْ قَالَ كَذَلِكَ النُّشُورُ قَالَ يَا رَسُولَ اللَّهِ وَمَا الْإِيمَانُ قَالَ أَنْ تَشْهَدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏عَبْدُهُ وَرَسُولُهُ وَأَنْ يَكُونَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْكَ مِمَّا سِوَاهُمَا وَأَنْ تُحْرَقَ بِالنَّارِ أَحَبُّ إِلَيْكَ مِنْ أَنْ تُشْرِكَ بِاللَّهِ وَأَنْ تُحِبَّ غَيْرَ ذِي نَسَبٍ لَا تُحِبُّهُ إِلَّا لِلَّهِ عَزَّ وَجَلَّ فَإِذَا كُنْتَ كَذَلِكَ فَقَدْ دَخَلَ حُبُّ الْإِيمَانِ فِي قَلْبِكَ كَمَا دَخَلَ حُبُّ الْمَاءِ لِلظَّمْآنِ فِي الْيَوْمِ ‏ ‏الْقَائِظِ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ لِي ‏ ‏بِأَنْ أَعْلَمَ أَنِّي مُؤْمِنٌ قَالَ مَا مِنْ أُمَّتِي ‏ ‏أَوْ هَذِهِ الْأُمَّةِ ‏ ‏عَبْدٌ يَعْمَلُ حَسَنَةً فَيَعْلَمُ أَنَّهَا حَسَنَةٌ وَأَنَّ اللَّهَ عَزَّ وَجَلَّ جَازِيهِ بِهَا خَيْرًا وَلَا يَعْمَلُ سَيِّئَةً فَيَعْلَمُ أَنَّهَا سَيِّئَةٌ وَاسْتَغْفَرَ اللَّهَ عَزَّ وَجَلَّ مِنْهَا وَيَعْلَمُ أَنَّهُ لَا يَغْفِرُ إِلَّا هُوَ إِلَّا وَهُوَ مُؤْمِنٌ ‏","","",""],[15606,15606,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏وَكِيعَ بْنَ حُدُسٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ رُؤْيَا الْمُسْلِمِ جُزْءٌ مِنْ أَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ وَهِيَ عَلَى رِجْلِ طَائِرٍ مَا لَمْ يُحَدِّثْ بِهَا فَإِذَا حَدَّثَ بِهَا وَقَعَتْ ‏ ‏قَالَ أَظُنُّهُ قَالَ لَا يُحَدِّثُ بِهَا إِلَّا حَبِيبًا أَوْ ‏ ‏لَبِيبًا ‏","","",""],[15607,15607,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ حُدُسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ يُحْيِي اللَّهُ الْمَوْتَى فَقَالَ ‏ ‏أَمَا مَرَرْتَ بِوَادٍ ‏ ‏مُمْحِلٍ ‏ ‏ثُمَّ مَرَرْتَ بِهِ خَصِيبًا ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏ثُمَّ تَمُرُّ بِهِ خَضِرًا ‏ ‏قَالَ قُلْتُ بَلَى قَالَ كَذَلِكَ يُحْيِي اللَّهُ الْمَوْتَى ‏","","",""],[15608,15608,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَبَهْزٌ ‏ ‏الْمَعْنَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏وَكِيعَ بْنَ حُدَسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُؤْيَا الْمُؤْمِنِ جُزْءٌ مِنْ أَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ وَهِيَ عَلَى رِجْلِ طَائِرٍ مَا لَمْ يُحَدِّثْ بِهَا فَإِذَا حَدَّثَ بِهَا سَقَطَتْ ‏ ‏وَأَحْسِبُهُ قَالَ لَا يُحَدِّثُ بِهَا إِلَّا حَبِيبًا أَوْ ‏ ‏لَبِيبًا ‏","","",""],[15609,15609,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ عُدُسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏الْعُقَيْلِيِّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَكُلُّنَا يَرَى رَبَّهُ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏كَيْفَ نَرَى رَبَّنَا ‏ ‏يَوْمَ الْقِيَامَةِ وَمَا آيَةُ ذَلِكَ فِي خَلْقِهِ فَقَالَ ‏ ‏أَلَيْسَ كُلُّكُمْ يَنْظُرُ إِلَى الْقَمَرِ مُخْلِيًا بِهِ قَالَ قُلْتُ بَلَى قَالَ فَإِنَّهُ أَعْظَمُ ‏","","",""],[15610,15610,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏النُّعْمَانُ بْنُ سَالِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ أَوْسٍ ‏ ‏قَالَ قَالَ ‏ ‏أَبُو رَزِينٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ أَبِي شَيْخٌ كَبِيرٌ لَا يُطِيقُ الْحَجَّ وَلَا الْعُمْرَةَ وَلَا ‏ ‏الظَّعْنَ ‏ ‏قَالَ ‏ ‏حُجَّ عَنْ أَبِيكَ وَاعْتَمِرْ ‏","","",""],[15611,15611,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ حُدُسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ الْعُقَيْلِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏أَيْنَ كَانَ رَبُّنَا عَزَّ وَجَلَّ قَبْلَ أَنْ يَخْلُقَ السَّمَوَاتِ وَالْأَرْضَ قَالَ فِي ‏ ‏عَمَاءٍ ‏ ‏مَا فَوْقَهُ هَوَاءٌ وَتَحْتَهُ هَوَاءٌ ثُمَّ خَلَقَ عَرْشَهُ عَلَى الْمَاءِ ‏","","",""],[15612,15612,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَسَنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ حُدَسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏الْعُقَيْلِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏ضَحِكَ رَبُّنَا مِنْ قُنُوطِ ‏ ‏عَبْدِهِ ‏ ‏وَقُرْبِ غَيْرِهِ قَالَ ‏ ‏أَبُو رَزِينٍ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ أَوَيَضْحَكُ الرَّبُّ عَزَّ وَجَلَّ الْعَظِيمُ لَنْ نَعْدَمَ مِنْ رَبٍّ يَضْحَكُ خَيْرًا ‏ ‏قَالَ ‏ ‏حَسَنٌ ‏ ‏فِي حَدِيثِهِ فَقَالَ نَعَمْ لَنْ نَعْدَمَ مِنْ رَبٍّ يَضْحَكُ خَيْرًا ‏","","",""],[15613,15613,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ حُدُسٍ الْعُقَيْلِيِّ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ وَهُوَ لَقِيطُ بْنُ عَامِرٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو رَزِينٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏إِنَّا كُنَّا نَذْبَحُ فِي رَجَبٍ ذَبَائِحَ فَنَأْكُلُ مِنْهَا وَنُطْعِمُ مِنْهَا مَنْ جَاءَنَا قَالَ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا بَأْسَ بِذَلِكَ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏وَكِيعٌ ‏ ‏فَلَا أَدَعُهَا أَبَدًا ‏","","",""],[15614,15614,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ أَوْسٍ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ ‏ ‏أَنَّ رَجُلًا أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ أَبِي أَدْرَكَ الْإِسْلَامَ وَهُوَ شَيْخٌ كَبِيرٌ لَا يَسْتَطِيعُ الْحَجَّ وَلَا الْعُمْرَةَ وَلَا ‏ ‏الظَّعْنَ ‏ ‏قَالَ ‏ ‏حُجَّ عَنْ أَبِيكَ وَاعْتَمِرْ ‏","","",""],[15615,15615,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ حُدَسٍ أَبِي مُصْعَبَ الْعُقَيْلِيِّ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏أَبِي رَزِينٍ وَهُوَ لَقِيطُ بْنُ عَامِرِ بْنِ الْمُنْتَفِقِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو رَزِينٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏إِنَّا كُنَّا نَذْبَحُ فِي رَجَبٍ ذَبَائِحَ فَنَأْكُلُ مِنْهَا وَنُطْعِمُ مِنْهَا ‏ ‏مَنْ جَاءَنَا قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا بَأْسَ بِذَلِكَ ‏ ‏فَقَالَ ‏ ‏وَكِيعٌ ‏ ‏لَا أَدَعُهَا أَبَدًا ‏","","",""],[15616,15616,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنْ ‏ ‏وَكِيعِ بْنِ حُدُسٍ ‏ ‏عَنْ ‏ ‏أَبِي رَزِينٍ ‏ ‏عَمِّهِ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رُؤْيَا الْمُسْلِمِ جُزْءٌ مِنْ أَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ وَهِيَ ‏ ‏يَعْنِي عَلَى رِجْلِ طَائِرٍ مَا لَمْ يُحَدِّثْ بِهَا فَإِذَا حَدَّثَ بِهَا وَقَعَتْ ‏","","",""],[15617,15617,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏كَتَبَ إِلَيَّ ‏ ‏إِبْرَاهِيمُ بْنُ حَمْزَةَ بْنِ مُحَمَّدِ بْنِ حَمْزَةَ بْنِ مُصْعَبِ بْنِ الزُّبَيْرِ ‏ ‏كَتَبْتُ إِلَيْكَ بِهَذَا الْحَدِيثِ وَقَدْ عَرَضْتُهُ وَجَمَعْتُهُ عَلَى مَا كَتَبْتُ بِهِ إِلَيْكَ فَحَدِّثْ بِذَلِكَ عَنِّي ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْمُغِيرَةِ الْحِزَامِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَيَّاشٍ السَّمَعِيُّ الْأَنْصَارِيُّ الْقُبَائِيُّ ‏ ‏مِنْ ‏ ‏بَنِي عَمْرِو بْنِ عَوْفٍ ‏ ‏عَنْ ‏ ‏دَلْهَمِ بْنِ الْأَسْوَدِ بْنِ عَبْدِ اللَّهِ بْنِ حَاجِبِ بْنِ عَامِرِ بْنِ الْمُنْتَفِقِ الْعُقَيْلِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏لَقِيطِ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏دَلْهَمٌ ‏ ‏وَحَدَّثَنِيهِ ‏ ‏أَبِي الْأَسْوَدُ ‏ ‏عَنِ ‏ ‏عَاصِمِ بْنِ لَقِيطٍ ‏ ‏أَنَّ ‏ ‏لَقِيطًا ‏ ‏خَرَجَ وَافِدًا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ صَاحِبٌ لَهُ يُقَالُ لَهُ ‏ ‏نَهِيكُ بْنُ عَاصِمِ بْنِ مَالِكِ بْنِ الْمُنْتَفِقِ ‏ ‏قَالَ ‏ ‏لَقِيطٌ ‏ ‏فَخَرَجْتُ أَنَا وَصَاحِبِي حَتَّى قَدِمْنَا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِانْسِلَاخِ ‏ ‏رَجَبٍ فَأَتَيْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَوَافَيْنَاهُ حِينَ انْصَرَفَ مِنْ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏فَقَامَ فِي النَّاسِ خَطِيبًا فَقَالَ أَيُّهَا النَّاسُ أَلَا إِنِّي قَدْ خَبَّأْتُ لَكُمْ صَوْتِي مُنْذُ أَرْبَعَةِ أَيَّامٍ أَلَا لَأُسْمِعَنَّكُمْ أَلَا فَهَلْ مِنْ امْرِئٍ بَعَثَهُ قَوْمُهُ فَقَالُوا اعْلَمْ لَنَا مَا يَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا ثُمَّ لَعَلَّهُ أَنْ يُلْهِيَهُ حَدِيثُ نَفْسِهِ أَوْ حَدِيثُ صَاحِبِهِ أَوْ يُلْهِيَهُ الضُّلَّالُ أَلَا إِنِّي مَسْئُولٌ هَلْ بَلَّغْتُ أَلَا اسْمَعُوا تَعِيشُوا أَلَا اجْلِسُوا أَلَا اجْلِسُوا قَالَ فَجَلَسَ النَّاسُ وَقُمْتُ أَنَا وَصَاحِبِي حَتَّى إِذَا فَرَغَ لَنَا فُؤَادُهُ وَبَصَرُهُ قُلْتُ يَا رَسُولَ اللَّهِ مَا عِنْدَكَ مِنْ عِلْمِ الْغَيْبِ فَضَحِكَ لَعَمْرُ اللَّهِ وَهَزَّ رَأْسَهُ وَعَلِمَ أَنِّي ‏ ‏أَبْتَغِي لِسَقَطِهِ فَقَالَ ‏ ‏ضَنَّ رَبُّكَ عَزَّ وَجَلَّ بِمَفَاتِيحِ خَمْسٍ مِنْ الْغَيْبِ لَا يَعْلَمُهَا إِلَّا اللَّهُ وَأَشَارَ بِيَدِهِ قُلْتُ وَمَا هِيَ قَالَ عِلْمُ ‏ ‏الْمَنِيَّةِ ‏ ‏قَدْ عَلِمَ ‏ ‏مَنِيَّةَ ‏ ‏أَحَدِكُمْ وَلَا تَعْلَمُونَهُ وَعِلْمُ ‏ ‏الْمَنِيِّ ‏ ‏حِينَ يَكُونُ فِي الرَّحِمِ قَدْ عَلِمَهُ وَلَا تَعْلَمُونَ وَعَلِمَ مَا فِي غَدٍ وَمَا أَنْتَ طَاعِمٌ غَدًا وَلَا تَعْلَمُهُ وَعَلِمَ الْيَوْمَ ‏ ‏الْغَيْثَ ‏ ‏يُشْرِفُ عَلَيْكُمْ ‏ ‏آزِلِينَ ‏ ‏آدِلِينَ ‏ ‏مُشْفِقِينَ فَيَظَلُّ يَضْحَكُ قَدْ عَلِمَ أَنَّ غَيْرَكُمْ إِلَى قُرْبٍ قَالَ ‏ ‏لَقِيطٌ ‏ ‏لَنْ نَعْدَمَ مِنْ رَبٍّ يَضْحَكُ خَيْرًا وَعَلِمَ يَوْمَ السَّاعَةِ قُلْتُ يَا رَسُولَ اللَّهِ عَلِّمْنَا مِمَّا تُعَلِّمُ النَّاسَ وَمَا تَعْلَمُ فَإِنَّا مِنْ قَبِيلٍ لَا يُصَدِّقُونَ تَصْدِيقَنَا أَحَدٌ مِنْ ‏ ‏مَذْحِجٍ ‏ ‏الَّتِي ‏ ‏تَرْبَأُ ‏ ‏عَلَيْنَا ‏ ‏وَخَثْعَمٍ ‏ ‏الَّتِي ‏ ‏تُوَالِينَا وَعَشِيرَتِنَا الَّتِي نَحْنُ مِنْهَا قَالَ تَلْبَثُونَ مَا لَبِثْتُمْ ثُمَّ يُتَوَفَّى نَبِيُّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ تَلْبَثُونَ مَا لَبِثْتُمْ ثُمَّ تُبْعَثُ الصَّائِحَةُ لَعَمْرُ إِلَهِكَ مَا تَدَعُ عَلَى ظَهْرِهَا مِنْ شَيْءٍ إِلَّا مَاتَ وَالْمَلَائِكَةُ الَّذِينَ مَعَ رَبِّكَ عَزَّ وَجَلَّ فَأَصْبَحَ رَبُّكَ عَزَّ وَجَلَّ يُطِيفُ فِي الْأَرْضِ وَخَلَتْ عَلَيْهِ الْبِلَادُ فَأَرْسَلَ رَبُّكَ عَزَّ وَجَلَّ السَّمَاءَ ‏ ‏بِهَضْبٍ ‏ ‏مِنْ عِنْدِ الْعَرْشِ فَلَعَمْرُ إِلَهِكَ مَا تَدَعُ عَلَى ظَهْرِهَا مِنْ ‏ ‏مَصْرَعِ ‏ ‏قَتِيلٍ وَلَا مَدْفِنِ مَيِّتٍ إِلَّا شَقَّتْ الْقَبْرَ عَنْهُ حَتَّى تَجْعَلَهُ مِنْ عِنْدِ رَأْسِهِ ‏ ‏فَيَسْتَوِي جَالِسًا فَيَقُولُ رَبُّكَ ‏ ‏مَهْيَمْ ‏ ‏لِمَا كَانَ فِيهِ يَقُولُ يَا رَبِّ أَمْسِ الْيَوْمَ وَلِعَهْدِهِ بِالْحَيَاةِ يَحْسَبُهُ حَدِيثًا بِأَهْلِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ يَجْمَعُنَا بَعْدَ مَا تُمَزِّقُنَا الرِّيَاحُ ‏ ‏وَالْبِلَى وَالسِّبَاعُ قَالَ أُنَبِّئُكَ بِمِثْلِ ذَلِكَ فِي ‏ ‏آلَاءِ ‏ ‏اللَّهِ الْأَرْضُ أَشْرَفْتَ عَلَيْهَا وَهِيَ ‏ ‏مَدَرَةٌ ‏ ‏بَالِيَةٌ فَقُلْتَ لَا ‏ ‏تَحْيَا أَبَدًا ثُمَّ أَرْسَلَ رَبُّكَ عَزَّ وَجَلَّ عَلَيْهَا السَّمَاءَ فَلَمْ تَلْبَثْ عَلَيْكَ إِلَّا أَيَّامًا حَتَّى أَشْرَفْتَ عَلَيْهَا وَهِيَ ‏ ‏شَرْيَةٌ ‏ ‏وَاحِدَةٌ وَلَعَمْرُ إِلَهِكَ لَهُوَ أَقْدَرُ عَلَى أَنْ يَجْمَعَهُمْ مِنْ الْمَاءِ عَلَى أَنْ يَجْمَعَ نَبَاتَ الْأَرْضِ فَيَخْرُجُونَ مِنْ ‏ ‏الْأَصْوَاءِ ‏ ‏وَمِنْ ‏ ‏مَصَارِعِهِمْ ‏ ‏فَتَنْظُرُونَ إِلَيْهِ وَيَنْظُرُ إِلَيْكُمْ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ كَيْفَ نَحْنُ مِلْءُ الْأَرْضِ وَهُوَ شَخْصٌ وَاحِدٌ نَنْظُرُ إِلَيْهِ وَيَنْظُرُ إِلَيْنَا قَالَ أُنَبِّئُكَ بِمِثْلِ ذَلِكَ فِي ‏ ‏آلَاءِ ‏ ‏اللَّهِ عَزَّ وَجَلَّ الشَّمْسُ وَالْقَمَرُ آيَةٌ مِنْهُ صَغِيرَةٌ تَرَوْنَهُمَا وَيَرَيَانِكُمْ سَاعَةً وَاحِدَةً لَا ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَتِهِمَا وَلَعَمْرُ إِلَهِكَ لَهُوَ أَقْدَرُ عَلَى أَنْ ‏ ‏يَرَاكُمْ وَتَرَوْنَهُ مِنْ أَنْ تَرَوْنَهُمَا وَيَرَيَانِكُمْ لَا ‏ ‏تُضَارُّونَ ‏ ‏فِي رُؤْيَتِهِمَا قُلْتُ ‏ ‏يَا رَسُولَ اللَّهِ فَمَا يَفْعَلُ بِنَا رَبُّنَا عَزَّ وَجَلَّ إِذَا لَقِينَاهُ قَالَ تُعْرَضُونَ عَلَيْهِ بَادِيَةٌ لَهُ صَفَحَاتُكُمْ لَا ‏ ‏يَخْفَى عَلَيْهِ مِنْكُمْ خَافِيَةٌ فَيَأْخُذُ رَبُّكَ عَزَّ وَجَلَّ بِيَدِهِ غَرْفَةً مِنْ الْمَاءِ ‏ ‏فَيَنْضَحُ ‏ ‏قَبِيلَكُمْ بِهَا فَلَعَمْرُ إِلَهِكَ مَا تُخْطِئُ وَجْهَ أَحَدِكُمْ مِنْهَا قَطْرَةٌ فَأَمَّا الْمُسْلِمُ فَتَدَعُ وَجْهَهُ مِثْلَ ‏ ‏الرَّيْطَةِ ‏ ‏الْبَيْضَاءِ وَأَمَّا الْكَافِرُ ‏ ‏فَتَخْطِمُهُ ‏ ‏مِثْلَ ‏ ‏الْحَمِيمِ ‏ ‏الْأَسْوَدِ أَلَا ثُمَّ يَنْصَرِفُ نَبِيُّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيَفْتَرِقُ عَلَى أَثَرِهِ الصَّالِحُونَ فَيَسْلُكُونَ جِسْرًا مِنْ النَّارِ ‏ ‏فَيَطَأُ ‏ ‏أَحَدُكُمْ الْجَمْرَ فَيَقُولُ حَسِّ يَقُولُ رَبُّكَ عَزَّ وَجَلَّ أَوَانُهُ أَلَا فَتَطَّلِعُونَ عَلَى حَوْضِ الرَّسُولِ عَلَى ‏ ‏أَظْمَأِ وَاللَّهِ ‏ ‏نَاهِلَةٍ ‏ ‏عَلَيْهَا قَطُّ مَا رَأَيْتُهَا فَلَعَمْرُ إِلَهِكَ مَا يَبْسُطُ وَاحِدٌ مِنْكُمْ يَدَهُ إِلَّا وُضِعَ عَلَيْهَا ‏ ‏قَدَحٌ ‏ ‏يُطَهِّرُهُ مِنْ الطَّوْفِ وَالْبَوْلِ وَالْأَذَى وَتُحْبَسُ الشَّمْسُ وَالْقَمَرُ وَلَا تَرَوْنَ مِنْهُمَا وَاحِدًا قَالَ قُلْتُ يَا رَسُولَ اللَّهِ فَبِمَا نُبْصِرُ قَالَ بِمِثْلِ بَصَرِكَ سَاعَتَكَ هَذِهِ وَذَلِكَ قَبْلَ طُلُوعِ الشَّمْسِ فِي يَوْمٍ أَشْرَقَتْ الْأَرْضُ وَاجَهَتْ بِهِ الْجِبَالَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ فَبِمَا ‏ ‏نُجْزَى مِنْ سَيِّئَاتِنَا وَحَسَنَاتِنَا قَالَ الْحَسَنَةُ بِعَشْرِ أَمْثَالِهَا وَالسَّيِّئَةُ بِمِثْلِهَا إِلَّا أَنْ يَعْفُوَ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ إِمَّا الْجَنَّةُ إِمَّا النَّارُ قَالَ لَعَمْرُ إِلَهِكَ إِنَّ لِلنَّارِ لَسَبْعَةَ أَبْوَابٍ مَا مِنْهُنَّ بَابَانِ إِلَّا يَسِيرُ الرَّاكِبُ بَيْنَهُمَا سَبْعِينَ عَامًا وَإِنَّ لِلْجَنَّةِ لَثَمَانِيَةَ أَبْوَابٍ مَا مِنْهُمَا بَابَانِ إِلَّا يَسِيرُ الرَّاكِبُ بَيْنَهُمَا سَبْعِينَ عَامًا قُلْتُ يَا رَسُولَ اللَّهِ فَعَلَى مَا نَطَّلِعُ مِنْ الْجَنَّةِ قَالَ عَلَى أَنْهَارٍ مِنْ عَسَلٍ مُصَفًّى وَأَنْهَارٍ مِنْ كَأْسٍ مَا بِهَا مِنْ صُدَاعٍ وَلَا نَدَامَةٍ وَأَنْهَارٍ مِنْ لَبَنٍ لَمْ يَتَغَيَّرْ طَعْمُهُ وَمَاءٍ غَيْرِ ‏ ‏آسِنٍ ‏ ‏وَبِفَاكِهَةٍ لَعَمْرُ إِلَهِكَ مَا تَعْلَمُونَ وَخَيْرٌ مِنْ مِثْلِهِ مَعَهُ وَأَزْوَاجٌ مُطَهَّرَةٌ قُلْتُ يَا رَسُولَ اللَّهِ وَلَنَا فِيهَا أَزْوَاجٌ ‏ ‏أَوْ مِنْهُنَّ مُصْلِحَاتٌ ‏ ‏قَالَ الصَّالِحَاتُ لِلصَّالِحِينَ تَلَذُّونَهُنَّ مِثْلَ لَذَّاتِكُمْ فِي الدُّنْيَا وَيَلْذَذْنَ بِكُمْ غَيْرَ أَنْ لَا تَوَالُدَ قَالَ ‏ ‏لَقِيطٌ ‏ ‏فَقُلْتُ أَقُضِيَ مَا نَحْنُ بَالِغُونَ وَمُنْتَهُونَ إِلَيْهِ فَلَمْ يُجِبْهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَا أُبَايِعُكَ قَالَ فَبَسَطَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ وَقَالَ عَلَى إِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ وَزِيَالِ الْمُشْرِكِ وَأَنْ لَا تُشْرِكَ بِاللَّهِ إِلَهًا غَيْرَهُ قُلْتُ وَإِنَّ لَنَا مَا بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ فَقَبَضَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ وَظَنَّ أَنِّي مُشْتَرِطٌ شَيْئًا لَا ‏ ‏يُعْطِينِيهِ قَالَ قُلْتُ نَحِلُّ مِنْهَا حَيْثُ شِئْنَا وَلَا ‏ ‏يَجْنِي امْرُؤٌ إِلَّا عَلَى نَفْسِهِ فَبَسَطَ يَدَهُ وَقَالَ ذَلِكَ لَكَ تَحِلُّ حَيْثُ شِئْتَ وَلَا ‏ ‏يَجْنِي عَلَيْكَ إِلَّا نَفْسُكَ قَالَ فَانْصَرَفْنَا عَنْهُ ثُمَّ قَالَ إِنَّ هَذَيْنِ لَعَمْرُ إِلَهِكَ مِنْ أَتْقَى النَّاسِ فِي الْأُولَى وَالْآخِرَةِ فَقَالَ لَهُ ‏ ‏كَعْبُ ابْنُ الْخُدْرِيَّةِ ‏ ‏أَحَدُ ‏ ‏بَنِي بَكْرِ بْنِ كِلَابٍ ‏ ‏مِنْ هُمْ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏بَنُو الْمُنْتَفِقِ ‏ ‏أَهْلُ ذَلِكَ قَالَ فَانْصَرَفْنَا وَأَقْبَلْتُ عَلَيْهِ فَقُلْتُ يَا رَسُولَ اللَّهِ هَلْ لِأَحَدٍ مِمَّنْ مَضَى مِنْ خَيْرٍ فِي جَاهِلِيَّتِهِمْ قَالَ قَالَ رَجُلٌ مِنْ ‏ ‏عُرْضِ ‏ ‏قُرَيْشٍ ‏ ‏وَاللَّهِ إِنَّ أَبَاكَ ‏ ‏الْمُنْتَفِقَ ‏ ‏لَفِي النَّارِ قَالَ فَلَكَأَنَّهُ وَقَعَ حَرٌّ بَيْنَ جِلْدِي وَوَجْهِي وَلَحْمِي مِمَّا قَالَ لِأَبِي عَلَى رُءُوسِ النَّاسِ فَهَمَمْتُ أَنْ أَقُولَ وَأَبُوكَ يَا رَسُولَ اللَّهِ ثُمَّ إِذَا الْأُخْرَى أَجْهَلُ فَقُلْتُ يَا رَسُولَ اللَّهِ وَأَهْلُكَ قَالَ وَأَهْلِي لَعَمْرُ اللَّهِ مَا أَتَيْتَ عَلَيْهِ مِنْ قَبْرِ عَامِرِيٍّ أَوْ قُرَشِيٍّ مِنْ مُشْرِكٍ فَقُلْ أَرْسَلَنِي إِلَيْكَ ‏ ‏مُحَمَّدٌ ‏ ‏فَأُبَشِّرُكَ بِمَا يَسُوءُكَ تُجَرُّ عَلَى وَجْهِكَ وَبَطْنِكَ فِي النَّارِ قَالَ قُلْتُ يَا رَسُولَ اللَّهِ مَا فَعَلَ بِهِمْ ذَلِكَ وَقَدْ كَانُوا عَلَى عَمَلٍ لَا يُحْسِنُونَ إِلَّا إِيَّاهُ وَكَانُوا يَحْسِبُونَ أَنَّهُمْ مُصْلِحُونَ قَالَ ذَلِكَ لِأَنَّ اللَّهَ عَزَّ وَجَلَّ بَعَثَ فِي آخِرِ كُلِّ سَبْعِ أُمَمٍ ‏ ‏يَعْنِي نَبِيًّا فَمَنْ عَصَى نَبِيَّهُ كَانَ مِنْ الضَّالِّينَ وَمَنْ أَطَاعَ نَبِيَّهُ كَانَ مِنْ الْمُهْتَدِينَ ‏","","",""],[15618,15618,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ الْحَجَّاجِ النَّاجِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْقَاهِرِ بْنُ السَّرِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنٌ لِكِنَانَةَ بْنِ عَبَّاسِ بْنِ مِرْدَاسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏الْعَبَّاسَ بْنَ مِرْدَاسٍ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا عَشِيَّةَ ‏ ‏عَرَفَةَ ‏ ‏لِأُمَّتِهِ بِالْمَغْفِرَةِ وَالرَّحْمَةِ فَأَكْثَرَ الدُّعَاءَ فَأَجَابَهُ اللَّهُ عَزَّ وَجَلَّ أَنْ قَدْ فَعَلْتُ وَغَفَرْتُ لِأُمَّتِكَ إِلَّا مَنْ ظَلَمَ بَعْضُهُمْ بَعْضًا فَقَالَ يَا رَبِّ إِنَّكَ قَادِرٌ أَنْ تَغْفِرَ لِلظَّالِمِ وَتُثِيبَ الْمَظْلُومَ خَيْرًا مِنْ مَظْلَمَتِهِ فَلَمْ يَكُنْ فِي تِلْكَ الْعَشِيَّةِ إِلَّا ذَا فَلَمَّا ‏ ‏كَانَ مِنْ الْغَدِ دَعَا ‏ ‏غَدَاةَ ‏ ‏الْمُزْدَلِفَةِ ‏ ‏فَعَادَ يَدْعُو لِأُمَّتِهِ فَلَمْ يَلْبَثْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تَبَسَّمَ فَقَالَ بَعْضُ أَصْحَابِهِ يَا رَسُولَ اللَّهِ بِأَبِي أَنْتَ وَأُمِّي ضَحِكْتَ فِي سَاعَةٍ لَمْ تَكُنْ تَضْحَكُ فِيهَا فَمَا أَضْحَكَكَ أَضْحَكَ اللَّهُ سِنَّكَ قَالَ تَبَسَّمْتُ مِنْ عَدُوِّ اللَّهِ إِبْلِيسَ حِينَ عَلِمَ أَنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ اسْتَجَابَ لِي فِي أُمَّتِي وَغَفَرَ لِلظَّالِمِ أَهْوَى يَدْعُو ‏ ‏بِالثُّبُورِ ‏ ‏وَالْوَيْلِ ‏ ‏وَيَحْثُو ‏ ‏التُّرَابَ عَلَى رَأْسِهِ فَتَبَسَّمْتُ مِمَّا يَصْنَعُ ‏ ‏جَزَعُهُ ‏","","",""],[15619,15619,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي خَالِدٍ ‏ ‏وَزَكَرِيَّا ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ مُضَرِّسٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏بِجَمْعٍ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ جِئْتُكَ مِنْ ‏ ‏جَبَلَيْ طَيِّءٍ ‏ ‏أَتْعَبْتُ نَفْسِي ‏ ‏وَأَنْصَبْتُ رَاحِلَتِي وَاللَّهِ مَا تَرَكْتُ مِنْ جَبَلٍ إِلَّا وَقَفْتُ عَلَيْهِ فَهَلْ لِي مِنْ حَجٍّ فَقَالَ ‏ ‏مَنْ شَهِدَ مَعَنَا هَذِهِ الصَّلَاةَ ‏ ‏يَعْنِي صَلَاةَ الْفَجْرِ ‏ ‏بِجَمْعٍ ‏ ‏وَوَقَفَ مَعَنَا حَتَّى ‏ ‏نُفِيضَ ‏ ‏مِنْهُ وَقَدْ ‏ ‏أَفَاضَ ‏ ‏قَبْلَ ذَلِكَ مِنْ ‏ ‏عَرَفَاتٍ ‏ ‏لَيْلًا أَوْ نَهَارًا فَقَدْ تَمَّ حَجُّهُ وَقَضَى ‏ ‏تَفَثَهُ ‏","","",""],[15620,15620,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَكَرِيَّا ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ مُضَرِّسِ بْنِ أَوْسِ بْنِ حَارِثَةَ بْنِ لَامٍ ‏ ‏أَنَّهُ حَجَّ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يُدْرِكْ النَّاسَ إِلَّا لَيْلًا وَهُوَ ‏ ‏بِجَمْعٍ ‏ ‏فَانْطَلَقَ إِلَى ‏ ‏عَرَفَاتٍ ‏ ‏فَأَفَاضَ ‏ ‏مِنْهَا ثُمَّ رَجَعَ فَأَتَى ‏ ‏جَمْعًا ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ أَتْعَبْتُ نَفْسِي ‏ ‏وَأَنْصَبْتُ ‏ ‏رَاحِلَتِي ‏ ‏فَهَلْ لِي مِنْ حَجٍّ فَقَالَ ‏ ‏مَنْ صَلَّى مَعَنَا صَلَاةَ ‏ ‏الْغَدَاةِ ‏ ‏بِجَمْعٍ ‏ ‏وَوَقَفَ مَعَنَا حَتَّى ‏ ‏نُفِيضَ ‏ ‏وَقَدْ ‏ ‏أَفَاضَ ‏ ‏قَبْلَ ذَلِكَ مِنْ ‏ ‏عَرَفَاتٍ ‏ ‏لَيْلًا أَوْ نَهَارًا فَقَدْ تَمَّ حَجُّهُ وَقَضَى ‏ ‏تَفَثَهُ ‏","","",""],[15621,15621,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ أُخْبِرْتُ أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏و عَنْ ‏ ‏سُلَيْمَانَ بْنِ مُوسَى ‏ ‏عَنْ ‏ ‏فُلَانٍ ‏ ‏و عَنْ ‏ ‏أَبِي الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏وَلَمْ يَبْلُغْ ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏هَذِهِ الْقِصَّةَ كُلَّهَا ‏ ‏أَنَّ ‏ ‏أَبَا قَتَادَةَ ‏ ‏أَتَى أَهْلَهُ فَوَجَدَ ‏ ‏قَصْعَةَ ‏ ‏ثَرِيدٍ ‏ ‏مِنْ ‏ ‏قَدِيدِ ‏ ‏الْأَضْحَى فَأَبَى أَنْ يَأْكُلَهُ فَأَتَى ‏ ‏قَتَادَةَ بْنَ النُّعْمَانِ ‏ ‏فَأَخْبَرَهُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فِي حَجٍّ فَقَالَ ‏ ‏إِنِّي كُنْتُ أَمَرْتُكُمْ أَنْ لَا تَأْكُلُوا الْأَضَاحِيَّ فَوْقَ ثَلَاثَةِ أَيَّامٍ لِتَسَعَكُمْ وَإِنِّي أُحِلُّهُ لَكُمْ فَكُلُوا مِنْهُ مَا شِئْتُمْ قَالَ وَلَا تَبِيعُوا لُحُومَ ‏ ‏الْهَدْيِ ‏ ‏وَالْأَضَاحِيِّ فَكُلُوا وَتَصَدَّقُوا وَاسْتَمْتِعُوا بِجُلُودِهَا وَإِنْ أُطْعِمْتُمْ مِنْ لُحُومِهَا شَيْئًا فَكُلُوهُ إِنْ شِئْتُمْ ‏","","",""],[15622,15622,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ قَالَ ‏ ‏سُلَيْمَانُ بْنُ مُوسَى ‏ ‏أَخْبَرَنِي ‏ ‏زُبَيْدٌ ‏ ‏أَنَّ ‏ ‏أَبَا سَعِيدٍ الْخُدْرِيَّ ‏ ‏أَتَى أَهْلَهُ فَوَجَدَ ‏ ‏قَصْعَةً ‏ ‏مِنْ ‏ ‏قَدِيدِ ‏ ‏الْأَضْحَى فَأَبَى أَنْ يَأْكُلَهُ فَأَتَى ‏ ‏قَتَادَةَ بْنَ النُّعْمَانِ ‏ ‏فَأَخْبَرَهُ أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فَقَالَ ‏ ‏إِنِّي كُنْتُ أَمَرْتُكُمْ أَنْ لَا تَأْكُلُوا الْأَضَاحِيَّ فَوْقَ ثَلَاثَةِ أَيَّامٍ لِتَسَعَكُمْ وَإِنِّي أُحِلُّهُ لَكُمْ فَكُلُوا مِنْهُ مَا شِئْتُمْ وَلَا تَبِيعُوا لُحُومَ ‏ ‏الْهَدْيِ ‏ ‏وَالْأَضَاحِيِّ فَكُلُوا وَتَصَدَّقُوا وَاسْتَمْتِعُوا بِجُلُودِهَا وَلَا تَبِيعُوهَا وَإِنْ أُطْعِمْتُمْ مِنْ لَحْمِهَا فَكُلُوا إِنْ شِئْتُمْ ‏ ‏و قَالَ ‏ ‏فِي هَذَا الْحَدِيثِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَالْآنَ فَكُلُوا وَاتَّجِرُوا وَادَّخِرُوا ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏نَحْوَ حَدِيثِ ‏ ‏زُبَيْدٍ ‏ ‏هَذَا عَنْ ‏ ‏أَبِي سَعِيدٍ ‏ ‏لَمْ يَبْلُغْهُ كُلُّ ذَلِكَ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15623,15623,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زُهَيْرٌ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏شَرِيكٍ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ أَبِي نَمِرٍ تَمِيمٍ ‏ ‏عَنِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَعَمِّهِ ‏ ‏قَتَادَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُوا لُحُومَ الْأَضَاحِيِّ وَادَّخِرُوا ‏","","",""],[15624,15624,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ عَلِيِّ بْنِ حُسَيْنِ بْنِ جَعْفَرٍ ‏ ‏وَأَبِي ‏ ‏إِسْحَاقُ بْنُ يَسَارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ خَبَّابٍ ‏ ‏مَوْلَى ‏ ‏بَنِي عَدِيِّ بْنِ النَّجَّارِ ‏ ‏عَنْ ‏ ‏أَبِي سَعِيدٍ الْخُدْرِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ نَهَانَا عَنْ أَنْ نَأْكُلَ لُحُومَ ‏ ‏نُسُكِنَا ‏ ‏فَوْقَ ثَلَاثٍ ‏ ‏قَالَ فَخَرَجْتُ فِي سَفَرٍ ثُمَّ قَدِمْتُ عَلَى أَهْلِي وَذَلِكَ بَعْدَ الْأَضْحَى بِأَيَّامٍ قَالَ فَأَتَتْنِي ‏ ‏صَاحِبَتِي ‏ ‏بِسَاقٍ قَدْ جَعَلَتْ فِيهِ ‏ ‏قَدِيدًا ‏ ‏فَقُلْتُ لَهَا أَنَّى لَكِ هَذَا ‏ ‏الْقَدِيدُ ‏ ‏فَقَالَتْ مِنْ ضَحَايَانَا قَالَ فَقُلْتُ لَهَا أَوَلَمْ يَنْهَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَنْ نَأْكُلَهَا فَوْقَ ثَلَاثٍ قَالَ فَقَالَتْ إِنَّهُ قَدْ رَخَّصَ لِلنَّاسِ بَعْدَ ذَلِكَ قَالَ فَلَمْ أُصَدِّقْهَا حَتَّى بَعَثْتُ إِلَى أَخِي ‏ ‏قَتَادَةَ بْنِ النُّعْمَانِ ‏ ‏وَكَانَ بَدْرِيًّا أَسْأَلُهُ عَنْ ذَلِكَ قَالَ فَبَعَثَ إِلَيَّ أَنْ كُلْ طَعَامَكَ فَقَدْ صَدَقَتْ قَدْ ‏ ‏أَرْخَصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلْمُسْلِمِينَ فِي ذَلِكَ ‏","","",""],[15625,15625,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏رِفَاعَةَ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كُنَّا ‏ ‏بِالْكَدِيدِ ‏ ‏أَوْ قَالَ ‏ ‏بِقُدَيْدٍ ‏ ‏فَجَعَلَ رِجَالٌ مِنَّا يَسْتَأْذِنُونَ إِلَى أَهْلِيهِمْ فَيَأْذَنُ لَهُمْ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ مَا بَالُ رِجَالٍ يَكُونُ ‏ ‏شِقُّ ‏ ‏الشَّجَرَةِ الَّتِي تَلِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَبْغَضَ إِلَيْهِمْ مِنْ الشِّقِّ الْآخَرِ فَلَمْ نَرَ عِنْدَ ذَلِكَ مِنْ الْقَوْمِ إِلَّا بَاكِيًا فَقَالَ رَجُلٌ إِنَّ الَّذِي يَسْتَأْذِنُكَ بَعْدَ هَذَا ‏ ‏لَسَفِيهٌ ‏ ‏فَحَمِدَ اللَّهَ وَقَالَ حِينَئِذٍ أَشْهَدُ عِنْدَ اللَّهِ لَا يَمُوتُ عَبْدٌ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّهِ صِدْقًا مِنْ قَلْبِهِ ثُمَّ يُسَدِّدُ إِلَّا سُلِكَ فِي الْجَنَّةِ قَالَ وَقَدْ وَعَدَنِي رَبِّي عَزَّ وَجَلَّ أَنْ يُدْخِلَ مِنْ أُمَّتِي سَبْعِينَ أَلْفًا لَا حِسَابَ عَلَيْهِمْ وَلَا عَذَابَ وَإِنِّي لَأَرْجُو أَنْ لَا يَدْخُلُوهَا حَتَّى ‏ ‏تَبَوَّءُوا ‏ ‏أَنْتُمْ وَمَنْ صَلَحَ مِنْ آبَائِكُمْ وَأَزْوَاجِكُمْ وَذُرِّيَّاتِكُمْ مَسَاكِنَ فِي الْجَنَّةِ وَقَالَ إِذَا مَضَى نِصْفُ اللَّيْلِ ‏ ‏أَوْ قَالَ ثُلُثَا اللَّيْلِ ‏ ‏يَنْزِلُ اللَّهُ عَزَّ وَجَلَّ إِلَى السَّمَاءِ الدُّنْيَا فَيَقُولُ ‏ ‏لَا أَسْأَلُ عَنْ عِبَادِي أَحَدًا غَيْرِي مَنْ ذَا يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ مَنْ الَّذِي يَدْعُونِي أَسْتَجِيبُ لَهُ مَنْ ذَا الَّذِي يَسْأَلُنِي أُعْطِيهِ حَتَّى ‏ ‏يَنْفَجِرَ ‏ ‏الصُّبْحُ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏رِفَاعَةَ بْنِ عَرَابَةَ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏صَدَرْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏مَكَّةَ ‏ ‏فَجَعَلَ النَّاسُ يَسْتَأْذِنُونَهُ فَذَكَرَ الْحَدِيثَ قَالَ وَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏إِنَّ الَّذِي يَسْتَأْذِنُكَ بَعْدَ هَذِهِ ‏ ‏لَسَفِيهٌ ‏ ‏فِي نَفْسِي ثُمَّ إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَمِدَ اللَّهَ وَقَالَ خَيْرًا ثُمَّ قَالَ أَشْهَدُ عِنْدَ اللَّهِ وَكَانَ إِذَا حَلَفَ قَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ مَا مِنْ عَبْدٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ثُمَّ يُسَدِّدُ إِلَّا سُلِكَ فِي الْجَنَّةِ فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى يَعْنِي ابْنَ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏هِلَالُ بْنُ أَبِي مَيْمُونَةَ ‏ ‏رَجُلٌ مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏رِفَاعَةَ بْنِ عَرَابَةَ الْجُهَنِيِّ ‏ ‏قَالَ ‏ ‏أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كُنَّا ‏ ‏بِالْكَدِيدِ ‏ ‏أَوْ قَالَ ‏ ‏بِعَرَفَةَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[15626,15626,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي الدَّسْتُوَائِيَّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ أَبِي مَيْمُونَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَطَاءُ بْنُ يَسَارٍ ‏ ‏أَنَّ ‏ ‏رِفَاعَةَ الْجُهَنِيَّ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كُنَّا ‏ ‏بِالْكَدِيدِ ‏ ‏أَوْ قَالَ ‏ ‏بِقُدَيْدٍ ‏ ‏جَعَلَ رِجَالٌ يَسْتَأْذِنُونَ إِلَى أَهْلِيهِمْ فَيُؤْذَنُ لَهُمْ قَالَ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ وَقَالَ خَيْرًا وَقَالَ أَشْهَدُ عِنْدَ اللَّهِ لَا يَمُوتُ عَبْدٌ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ صَادِقًا مِنْ قَلْبِهِ ثُمَّ يُسَدِّدُ إِلَّا سُلِكَ فِي الْجَنَّةِ ثُمَّ قَالَ وَعَدَنِي رَبِّي أَنْ يُدْخِلَ مِنْ أُمَّتِي سَبْعِينَ أَلْفًا بِغَيْرِ حِسَابٍ وَإِنِّي لَأَرْجُو أَنْ لَا يَدْخُلُوهَا حَتَّى ‏ ‏تَبَوَّءُوا ‏ ‏أَنْتُمْ وَمَنْ صَلَحَ مِنْ أَزْوَاجِكُمْ وَذَرَارِيِّكُمْ مَسَاكِنَ فِي الْجَنَّةِ وَقَالَ إِذَا مَضَى نِصْفُ اللَّيْلِ ‏ ‏أَوْ ثُلُثُ اللَّيْلِ ‏ ‏يَنْزِلُ اللَّهُ عَزَّ وَجَلَّ إِلَى السَّمَاءِ الدُّنْيَا فَيَقُولُ ‏ ‏لَا أَسْأَلُ عَنْ عِبَادِي أَحَدًا غَيْرِي مَنْ ذَا الَّذِي يَسْتَغْفِرُنِي أَغْفِرُ لَهُ مَنْ ذَا الَّذِي يَدْعُونِي فَأَسْتَجِيبَ لَهُ مَنْ ذَا الَّذِي يَسْأَلُنِي فَأُعْطِيَهُ حَتَّى ‏ ‏يَنْفَجِرَ ‏ ‏الصُّبْحُ ‏","","",""],[15627,15627,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏عَنْ ‏ ‏الرَّجُلِ ‏ ‏الَّذِي مَرَّ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يُنَاجِي ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏فَزَعَمَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَنَّهُ تَجَنَّبَ أَنْ ‏ ‏يَدْنُوَ ‏ ‏مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَخَوُّفًا أَنْ يَسْمَعَ حَدِيثَهُ فَلَمَّا أَصْبَحَ قَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مَنَعَكَ أَنْ تُسَلِّمَ إِذْ مَرَرْتَ بِي الْبَارِحَةَ قَالَ رَأَيْتُكَ ‏ ‏تُنَاجِي ‏ ‏رَجُلًا فَخَشِيتُ أَنْ تَكْرَهَ أَنْ ‏ ‏أَدْنُوَ ‏ ‏مِنْكُمَا قَالَ وَهَلْ تَدْرِي مَنْ الرَّجُلُ قَالَ لَا قَالَ ‏ ‏فَذَلِكَ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَلَوْ سَلَّمْتَ لَرَدَّ السَّلَامَ ‏ ‏وَقَدْ ‏ ‏سَمِعْتُ ‏ ‏مِنْ ‏ ‏غَيْرِ أَبِي سَلَمَةَ ‏ ‏أَنَّهُ ‏ ‏حَارِثَةَ بْنَ النُّعْمَانِ ‏","","",""],[15628,15628,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا مَالِكٍ الْأَشْجَعِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْ ‏ ‏رَأَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ قَدْ ‏ ‏خَالَفَ ‏ ‏بَيْنَ طَرَفَيْهِ ‏","","",""],[15629,15629,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَمْعَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ النِّسَاءَ فَوَعَظَ فِيهِنَّ وَقَالَ ‏ ‏عَلَامَ يَضْرِبُ أَحَدُكُمْ امْرَأَتَهُ وَلَعَلَّهُ أَنْ ‏ ‏يُضَاجِعَهَا ‏ ‏مِنْ آخِرِ النَّهَارِ أَوْ آخِرِ اللَّيْلِ ‏","","",""],[15630,15630,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَمْعَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ { ‏إِذْ انْبَعَثَ أَشْقَاهَا ‏} ‏انْبَعَثَ لَهَا رَجُلٌ ‏ ‏عَارِمٌ ‏ ‏عَزِيزٌ مَنِيعٌ فِي ‏ ‏رَهْطِهِ ‏ ‏مِثْلُ ‏ ‏أَبِي زَمْعَةَ ‏ ‏ثُمَّ وَعَظَهُمْ فِي الضَّحِكِ مِنْ ‏ ‏الضَّرْطَةِ ‏ ‏فَقَالَ إِلَى مَا يَضْحَكُ أَحَدُكُمْ مِمَّا يَفْعَلُ قَالَ ثُمَّ قَالَ إِلَى مَا يَجْلِدُ أَحَدُكُمْ امْرَأَتَهُ جَلْدَ الْعَبْدِ ثُمَّ لَعَلَّهُ أَنْ ‏ ‏يُضَاجِعَهَا ‏ ‏مِنْ آخِرِ يَوْمِهِ ‏","","",""],[15631,15631,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَمْعَةَ ‏ ‏قَالَ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ النَّاقَةَ وَذَكَرَ الَّذِي ‏ ‏عَقَرَهَا ‏ ‏فَقَالَ ‏ { ‏إِذْ انْبَعَثَ أَشْقَاهَا ‏} ‏انْبَعَثَ لَهَا رَجُلٌ ‏ ‏عَارِمٌ ‏ ‏عَزِيزٌ مَنِيعٌ فِي ‏ ‏رَهْطِهِ ‏ ‏مِثْلُ ‏ ‏أَبِي زَمْعَةَ ‏ ‏ثُمَّ ذَكَرَ النِّسَاءَ فَوَعَظَهُمْ فِيهِنَّ فَقَالَ عَلَامَ يَجْلِدُ أَحَدُكُمْ امْرَأَتَهُ جَلْدَ الْعَبْدِ وَلَعَلَّهُ ‏ ‏يُضَاجِعُهَا ‏ ‏مِنْ آخِرِ يَوْمِهِ ثُمَّ وَعَظَهُمْ فِي ضَحِكِهِمْ مِنْ ‏ ‏الضَّرْطَةِ ‏ ‏فَقَالَ عَلَامَ يَضْحَكُ أَحَدُكُمْ عَلَى مَا يَفْعَلُ ‏","","",""],[15632,15632,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَمْعَةَ ‏ ‏وَعَظَهُمْ فِي النِّسَاءِ وَقَالَ ‏ ‏عَلَامَ يَضْرِبُ أَحَدُكُمْ امْرَأَتَهُ ضَرْبَ الْعَبْدِ ثُمَّ ‏ ‏يُضَاجِعُهَا ‏ ‏مِنْ آخِرِ اللَّيْلِ ‏","","",""],[15633,15633,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنِ ‏ ‏الرَّبَابِ الضَّبِّيَّةِ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا أَفْطَرَ أَحَدُكُمْ فَلْيُفْطِرْ عَلَى تَمْرٍ فَإِنْ لَمْ يَجِدْ فَلْيُفْطِرْ عَلَى الْمَاءِ فَإِنَّ الْمَاءَ طَهُورٌ ‏ ‏قَالَ ‏ ‏هِشَامٌ ‏ ‏وَحَدَّثَنِي ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏أَنَّ ‏ ‏حَفْصَةَ ‏ ‏رَفَعَتْهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15634,15634,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنِ ‏ ‏الرَّبَابِ ‏ ‏عَنْ ‏ ‏عَمِّهَا ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَلْيُفْطِرْ عَلَى تَمْرٍ فَإِنْ لَمْ يَجِدْ فَلْيُفْطِرْ عَلَى مَاءٍ فَإِنَّهُ طَهُورٌ ‏","","",""],[15635,15635,"","","‏ ‏وَمَعَ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى وَأَرِيقُوا عَنْهُ دَمًا ‏ ‏وَالصَّدَقَةُ ‏ ‏عَلَى ذِي الْقَرَابَةِ ثِنْتَانِ ‏ ‏صَدَقَةٌ ‏ ‏وَصِلَةٌ ‏","","",""],[15636,15636,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ سِيرِينَ ‏ ‏عَنِ ‏ ‏الرَّبَابِ بِنْتِ صُلَيْعٍ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّدَقَةُ ‏ ‏عَلَى الْمِسْكِينِ ‏ ‏صَدَقَةٌ ‏ ‏وَهِيَ عَلَى ذِي الْقَرَابَةِ اثْنَتَانِ ‏ ‏صِلَةٌ ‏ ‏وَصَدَقَةٌ ‏","","",""],[15637,15637,"","","‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنِ ‏ ‏الرَّبَابِ ‏ ‏أُمِّ ‏ ‏الرَّائِحِ ‏ ‏ابْنَةِ ‏ ‏صُلَيْعٍ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَفْطَرَ أَحَدُكُمْ فَلْيُفْطِرْ عَلَى تَمْرٍ فَإِنْ لَمْ يَجِدْ فَلْيُفْطِرْ عَلَى مَاءٍ فَإِنَّهُ طَهُورٌ ‏","","",""],[15638,15638,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَابْنُ نُمَيْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ابْنَةِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ابْنُ نُمَيْرٍ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَعَ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ دَمًا ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[15639,15639,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَرِيقُوا ‏ ‏عَنْهُ دَمًا ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[15640,15640,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنِ ‏ ‏الرَّبَابِ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَفْطَرَ أَحَدُكُمْ فَلْيُفْطِرْ عَلَى تَمْرٍ فَإِنْ لَمْ يَجِدْ فَلْيُفْطِرْ عَلَى مَاءٍ فَإِنَّهُ طَهُورٌ ‏","","",""],[15641,15641,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ابْنَةِ سِيرِينَ ‏ ‏عَنِ ‏ ‏الرَّبَابِ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَفْطَرَ أَحَدُكُمْ فَلْيُفْطِرْ عَلَى تَمْرٍ فَإِنْ لَمْ يَجِدْ فَلْيُفْطِرْ بِمَاءٍ فَإِنَّ الْمَاءَ طَهُورٌ ‏","","",""],[15642,15642,"","","‏ ‏وَقَالَ ‏ ‏مَعَ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ دَمًا ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[15643,15643,"","","‏ ‏وَقَالَ ‏ ‏الصَّدَقَةُ ‏ ‏عَلَى الْمِسْكِينِ ‏ ‏صَدَقَةٌ ‏ ‏وَهِيَ عَلَى ذِي الرَّحِمِ اثْنَتَانِ صِلَةٌ ‏ ‏وَصَدَقَةٌ ‏","","",""],[15644,15644,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الصَّدَقَةُ ‏ ‏عَلَى الْمِسْكِينِ ‏ ‏صَدَقَةٌ ‏ ‏وَالصَّدَقَةُ ‏ ‏عَلَى ذِي الرَّحِمِ اثْنَتَانِ ‏ ‏صَدَقَةٌ ‏ ‏وَصِلَةٌ ‏","","",""],[15645,15645,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏حَفْصَةُ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَعَ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ دَمًا ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[15646,15646,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُهُ يَقُولُ ‏ ‏صَدَقَتُكَ ‏ ‏عَلَى الْمِسْكِينِ ‏ ‏صَدَقَةٌ ‏ ‏وَهِيَ عَلَى ذِي الرَّحِمِ ثِنْتَانِ ‏ ‏صَدَقَةٌ ‏ ‏وَصِلَةٌ ‏","","",""],[15647,15647,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ بِنْتِ سِيرِينَ ‏ ‏عَنْ ‏ ‏أُمِّ الرَّائِحِ ‏ ‏ابْنَةِ ‏ ‏صُلَيْعٍ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّدَقَةُ عَلَى الْمِسْكِينِ ‏ ‏صَدَقَةٌ ‏ ‏وَإِنَّهَا عَلَى ذِي الرَّحِمِ اثْنَتَانِ إِنَّهَا ‏ ‏صَدَقَةٌ ‏ ‏وَصِلَةٌ ‏","","",""],[15648,15648,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏وحَبِيبٌ ‏ ‏وَيُونُسُ ‏ ‏وَقَتَادَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ دَمًا ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[15649,15649,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنِ ‏ ‏الرَّبَابِ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَفْطَرَ أَحَدُكُمْ فَلْيُفْطِرْ عَلَى تَمْرٍ فَإِنْ لَمْ يَجِدْ تَمْرًا فَلْيُفْطِرْ عَلَى مَاءٍ فَإِنَّهُ لَهُ طَهُورٌ ‏","","",""],[15650,15650,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ ‏ ‏لَمْ يَذْكُرْ ‏ ‏أَيُّوبُ ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏سَلْمَانَ ‏ ‏رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏عَنْ الْغُلَامِ ‏ ‏عَقِيقَةٌ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ دَمًا ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[15651,15651,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏وَقَتَادَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ دَمًا ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[15652,15652,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الوَهَّابِ بْنُ عَطَاءٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏وَسَعِيدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَعَ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَرِيقُوا ‏ ‏عَنْهُ الدَّمَ ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏ ‏قَالَ ‏ ‏وَكَانَ ‏ ‏ابْنُ سِيرِينَ ‏ ‏يَقُولُ ‏ ‏إِنْ لَمْ تَكُنْ ‏ ‏إِمَاطَةُ ‏ ‏الْأَذَى حَلْقَ الرَّأْسِ فَلَا أَدْرِي مَا هُوَ ‏","","",""],[15653,15653,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ الضَّبِّيِّ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَعَ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏فَأَهْرِيقُوا ‏ ‏عَنْهُ الدَّمَ ‏ ‏وَأَمِيطُوا ‏ ‏عَنْهُ الْأَذَى ‏","","",""],[15654,15654,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏حَفْصَةَ ‏ ‏عَنْ ‏ ‏سَلْمَانَ بْنِ عَامِرٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ وَجَدَ تَمْرًا فَلْيُفْطِرْ عَلَيْهِ فَإِنْ لَمْ يَجِدْ تَمْرًا فَلْيُفْطِرْ عَلَى الْمَاءِ فَإِنَّ الْمَاءَ طَهُورٌ ‏","","",""],[15655,15655,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو خَيْثَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ عَبْدِ اللَّهِ بْنِ قُشَيْرٍ الْجُعْفِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏رَهْطٍ ‏ ‏مِنْ ‏ ‏مُزَيْنَةَ ‏ ‏فَبَايَعْنَا ‏ ‏وَإِنَّ قَمِيصَهُ ‏ ‏لَمُطْلَقٌ ‏ ‏فَبَايَعْتُهُ فَأَدْخَلْتُ يَدِي مِنْ جَيْبِ الْقَمِيصِ فَمَسِسْتُ ‏ ‏الْخَاتَمَ ‏ ‏قَالَ ‏ ‏عُرْوَةُ ‏ ‏فَمَا رَأَيْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏وَلَا أَبَاهُ شِتَاءً وَلَا حَرًّا إِلَّا مُطْلِقَيْ أَزْرَارِهِمَا لَا يَزُرَّانِ أَبَدًا ‏","","",""],[15656,15656,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بِسْطَامُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏قَالَ قَالَ ‏ ‏أَبِي ‏ ‏لَقَدْ عَمَّرْنَا مَعَ نَبِيِّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا لَنَا طَعَامٌ إِلَّا الْأَسْوَدَانِ ‏ ‏ثُمَّ ‏ ‏قَالَ ‏ ‏هَلْ تَدْرِي مَا الْأَسْوَدَانِ قُلْتُ لَا قَالَ التَّمْرُ وَالْمَاءُ ‏","","",""],[15657,15657,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ كَانَ حَلَبَ ‏ ‏وَصَرَّ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏كَانَ أَبِي حَدَّثَنَا عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا أَدْرِي أَسَمِعَهُ مِنْهُ أَوْ حُدِّثَ عَنْهُ ‏","","",""],[15658,15658,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدُ بْنُ مَيْسَرَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ هَاتَيْنِ الشَّجَرَتَيْنِ الْخَبِيثَتَيْنِ وَقَالَ ‏ ‏مَنْ أَكَلَهُمَا فَلَا يَقْرَبَنَّ مَسْجِدَنَا وَقَالَ إِنْ كُنْتُمْ لَا بُدَّ آكِلِيهِمَا ‏ ‏فَأَمِيتُمُوهُمَا طَبْخًا ‏ ‏قَالَ ‏ ‏يَعْنِي الْبَصَلَ وَالثُّومَ ‏","","",""],[15659,15659,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ أَبِي إِيَاسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏وَقَدْ كَانَ أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَسَحَ رَأْسَهُ وَاسْتَغْفَرَ لَهُ ‏","","",""],[15660,15660,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فِي صِيَامِ ثَلَاثَةِ أَيَّامٍ مِنْ الشَّهْرِ صَوْمُ الدَّهْرِ وَإِفْطَارُهُ ‏","","",""],[15661,15661,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِيَاسٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَبِي ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ غُلَامٌ صَغِيرٌ ‏ ‏فَمَسَحَ رَأْسَهُ وَاسْتَغْفَرَ لَهُ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قُلْنَا لَهُ صُحْبَةٌ قَالَ لَا وَلَكِنَّهُ ‏ ‏كَانَ عَلَى عَهْدِهِ قَدْ حَلَبَ ‏ ‏وَصَرَّ ‏","","",""],[15662,15662,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عَامِرٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏أُحُدٍ ‏ ‏أَصَابَ النَّاسَ ‏ ‏قَرْحٌ ‏ ‏وَجَهْدٌ شَدِيدٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْفِرُوا وَأَوْسِعُوا وَادْفِنُوا ‏ ‏الِاثْنَيْنِ وَالثَّلَاثَةَ فِي الْقَبْرِ قَالُوا يَا رَسُولَ اللَّهِ مَنْ نُقَدِّمُ قَالَ أَكْثَرَهُمْ جَمْعًا وَأَخْذًا لِلْقُرْآنِ ‏","","",""],[15663,15663,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ ‏ ‏كَانَ النَّاسُ يَشْتَرُونَ الذَّهَبَ ‏ ‏بِالْوَرِقِ ‏ ‏نَسِيئَةً ‏ ‏إِلَى الْعَطَاءِ فَأَتَى عَلَيْهِمْ ‏ ‏هِشَامُ بْنُ عَامِرٍ ‏ ‏فَنَهَاهُمْ وَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَانَا أَنْ نَبِيعَ الذَّهَبَ بِالْوَرِقِ ‏ ‏نَسِيئَةً ‏ ‏وَأَنْبَأَنَا ‏ ‏أَوْ قَالَ وَأَخْبَرَنَا ‏ ‏أَنَّ ذَلِكَ هُوَ الرِّبَا ‏","","",""],[15664,15664,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَشْيَاخِهِمْ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏هِشَامُ بْنُ عَامِرٍ ‏ ‏لِجِيرَانِهِ إِنَّكُمْ لَتَخُطُّونَ إِلَى رِجَالٍ مَا كَانُوا أَحْضَرَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَلَا أَوْعَى لِحَدِيثِهِ مِنِّي وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا بَيْنَ خَلْقِ ‏ ‏آدَمَ ‏ ‏إِلَى قِيَامِ السَّاعَةِ أَمْرٌ أَكْبَرُ مِنْ ‏ ‏الدَّجَّالِ ‏","","",""],[15665,15665,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏إِنَّكُمْ لَتَخُطُّونَ إِلَى أَقْوَامٍ مَا هُمْ بِأَعْلَمَ بِحَدِيثِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنَّا قُتِلَ أَبِي يَوْمَ ‏ ‏أُحُدٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْفِرُوا وَأَوْسِعُوا وَادْفِنُوا ‏ ‏الِاثْنَيْنِ وَالثَّلَاثَةَ فِي الْقَبْرِ وَقَدِّمُوا أَكْثَرَهُمْ قُرْآنًا ‏ ‏وَكَانَ أَبِي أَكْثَرَهُمْ قُرْآنًا فَقُدِّمَ ‏","","",""],[15666,15666,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ وَاللَّهِ ‏ ‏مَا بَيْنَ خَلْقِ ‏ ‏آدَمَ ‏ ‏إِلَى قِيَامِ السَّاعَةِ أَمْرٌ أَعْظَمُ مِنْ ‏ ‏الدَّجَّالِ ‏","","",""],[15667,15667,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏شَكَوْا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقَرْحَ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَقَالُوا كَيْفَ تَأْمُرُ بِقَتْلَانَا قَالَ ‏ ‏احْفِرُوا وَأَوْسِعُوا وَأَحْسِنُوا وَادْفِنُوا فِي الْقَبْرِ ‏ ‏الِاثْنَيْنِ وَالثَّلَاثَةَ وَقَدِّمُوا أَكْثَرَهُمْ قُرْآنًا ‏ ‏قَالَ ‏ ‏هِشَامٌ ‏ ‏فَقُدِّمَ أَبِي بَيْنَ يَدَيْ اثْنَيْنِ ‏","","",""],[15668,15668,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قَرَأْتُهُ عَلَيْهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُعَاذَةَ الْعَدَوِيَّةَ ‏ ‏قَالَتْ سَمِعْتُ ‏ ‏هِشَامَ بْنَ عَامِرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ مُسْلِمًا فَوْقَ ثَلَاثِ لَيَالٍ فَإِنْ كَانَ ‏ ‏تَصَارَمَا ‏ ‏فَوْقَ ثَلَاثٍ فَإِنَّهُمَا ‏ ‏نَاكِبَانِ ‏ ‏عَنْ الْحَقِّ مَا دَامَا عَلَى ‏ ‏صُرَامِهِمَا ‏ ‏وَأَوَّلُهُمَا ‏ ‏فَيْئًا ‏ ‏فَسَبْقُهُ ‏ ‏بِالْفَيْءِ ‏ ‏كَفَّارَتُهُ فَإِنْ سَلَّمَ عَلَيْهِ فَلَمْ يَرُدَّ عَلَيْهِ وَرَدَّ عَلَيْهِ سَلَامَهُ رَدَّتْ عَلَيْهِ الْمَلَائِكَةُ وَرَدَّ عَلَى الْآخَرِ الشَّيْطَانُ فَإِنْ مَاتَا عَلَى ‏ ‏صُرَامِهِمَا ‏ ‏لَمْ يَجْتَمِعَا فِي الْجَنَّةِ أَبَدًا ‏","","",""],[15669,15669,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عَامِرٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ مُسْلِمًا فَوْقَ ثَلَاثِ لَيَالٍ فَإِنَّهُمَا ‏ ‏نَاكِبَانِ ‏ ‏عَنْ الْحَقِّ مَا دَامَا عَلَى ‏ ‏صُرَامِهِمَا ‏ ‏وَأَوَّلُهُمَا ‏ ‏فَيْئًا ‏ ‏يَكُونُ سَبْقُهُ ‏ ‏بِالْفَيْءِ ‏ ‏كَفَّارَةً لَهُ وَإِنْ سَلَّمَ فَلَمْ يَقْبَلْ وَرَدَّ عَلَيْهِ سَلَامَهُ رَدَّتْ عَلَيْهِ الْمَلَائِكَةُ وَرَدَّ عَلَى الْآخَرِ الشَّيْطَانُ وَإِنْ مَاتَا عَلَى ‏ ‏صُرَامِهِمَا ‏ ‏لَمْ يَدْخُلَا الْجَنَّةَ جَمِيعًا أَبَدًا ‏","","",""],[15670,15670,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدُ بْنُ هِلَالٍ ‏ ‏قَالَ قَالَ ‏ ‏هِشَامُ بْنُ عَامِرٍ ‏ ‏جَاءَتْ ‏ ‏الْأَنْصَارُ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏فَقَالُوا يَا رَسُولَ اللَّهِ أَصَابَنَا ‏ ‏قَرْحٌ ‏ ‏وَجَهْدٌ فَكَيْفَ تَأْمُرُنَا قَالَ ‏ ‏احْفِرُوا وَأَوْسِعُوا وَاجْعَلُوا الرَّجُلَيْنِ وَالثَّلَاثَةَ فِي الْقَبْرِ قَالُوا فَأَيُّهُمْ نُقَدِّمُ قَالَ أَكْثَرَهُمْ قُرْآنًا ‏ ‏قَالَ ‏ ‏فَقُدِّمَ أَبِي ‏ ‏عَامِرٌ ‏ ‏بَيْنَ يَدَيْ رَجُلٍ أَوْ اثْنَيْنِ ‏","","",""],[15671,15671,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ رَأْسَ ‏ ‏الدَّجَّالِ ‏ ‏مِنْ وَرَائِهِ ‏ ‏حُبُكٌ ‏ ‏حُبُكٌ ‏ ‏فَمَنْ قَالَ أَنْتَ رَبِّي ‏ ‏افْتُتِنَ ‏ ‏وَمَنْ قَالَ كَذَبْتَ رَبِّي اللَّهُ عَلَيْهِ تَوَكَّلْتُ فَلَا يَضُرُّهُ ‏ ‏أَوْ قَالَ فَلَا ‏ ‏فِتْنَةَ ‏ ‏عَلَيْهِ ‏","","",""],[15672,15672,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامُ بْنُ عَامِرٍ ‏ ‏قَالَ ‏ ‏قُتِلَ أَبِي يَوْمَ ‏ ‏أُحُدٍ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْفِرُوا وَوَسِّعُوا وَأَحْسِنُوا وَادْفِنُوا ‏ ‏الِاثْنَيْنِ وَالثَّلَاثَةَ فِي الْقَبْرِ وَقَدِّمُوا أَكْثَرَهُمْ قُرْآنًا ‏ ‏فَكَانَ أَبِي ثَالِثَ ثَلَاثَةٍ وَكَانَ أَكْثَرَهُمْ قُرْآنًا فَقُدِّمَ ‏","","",""],[15673,15673,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّهْمَاءِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏شَكَوْا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بِهِمْ مِنْ ‏ ‏الْقَرْحِ ‏ ‏فَقَالَ ‏ ‏احْفِرُوا وَأَحْسِنُوا وَأَوْسِعُوا وَادْفِنُوا ‏ ‏الِاثْنَيْنِ وَالثَّلَاثَةَ فِي الْقَبْرِ وَقَدِّمُوا أَكْثَرَهُمْ قُرْآنًا ‏ ‏فَمَاتَ أَبِي فَقُدِّمَ بَيْنَ يَدَيْ رَجُلَيْنِ ‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمَيْدَ بْنَ هِلَالٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏هِشَامِ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏أُحُدٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏جَرِيرَ بْنَ حَازِمٍ ‏ ‏يُحَدِّثُ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏وَزَادَ فِيهِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏وَزَادَ فِيهِ وَأَعْمِقُوا ‏","","",""],[15674,15674,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ يَعْنِي ابْنَ هِلَالٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عَامِرٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا بَيْنَ خَلْقِ ‏ ‏آدَمَ ‏ ‏إِلَى أَنْ تَقُومَ السَّاعَةُ ‏ ‏فِتْنَةٌ ‏ ‏أَكْبَرُ مِنْ ‏ ‏فِتْنَةِ ‏ ‏الدَّجَّالِ ‏","","",""],[15675,15675,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ ‏ ‏قَدِمَ ‏ ‏هِشَامُ بْنُ عَامِرٍ ‏ ‏الْبَصْرَةَ ‏ ‏فَوَجَدَهُمْ يَتَبَايَعُونَ الذَّهَبَ فِي ‏ ‏أُعْطِيَاتِهِمْ فَقَامَ فَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ الذَّهَبِ ‏ ‏بِالْوَرِقِ ‏ ‏نَسِيئَةً ‏ ‏وَأَخْبَرَنَا ‏ ‏أَوْ قَالَ ‏ ‏إِنَّ ذَلِكَ هُوَ الرِّبَا ‏","","",""],[15676,15676,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي الدَّهْمَاءِ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عَامِرٍ ‏ ‏قَالَ ‏ ‏إِنَّكُمْ لَتُجَاوِزُونَ إِلَى رَهْطٍ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا كَانُوا أَحْصَى وَلَا أَحْفَظَ لِحَدِيثِهِ مِنِّي وَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا بَيْنَ ‏ ‏آدَمَ ‏ ‏إِلَى يَوْمِ الْقِيَامَةِ أَمْرٌ أَكْبَرُ مِنْ ‏ ‏الدَّجَّالِ ‏","","",""],[15677,15677,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكُ بْنُ أَنَسٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ خُصَيْفَةَ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ عَبْدِ اللَّهِ بْنِ كَعْبٍ السُّلَمِيَّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏نَافِعَ بْنَ جُبَيْرٍ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ أَبِي الْعَاصِ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عُثْمَانُ ‏ ‏وَبِي وَجَعٌ قَدْ كَادَ يُهْلِكُنِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمْسِكْ بِيَمِينِكَ سَبْعَ مَرَّاتٍ وَقُلْ أَعُوذُ بِعِزَّةِ اللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ ‏ ‏قَالَ ‏ ‏فَفَعَلْتُ ذَلِكَ فَأَذْهَبَ اللَّهُ مَا كَانَ بِي فَلَمْ أَزَلْ آمُرُ بِهِ أَهْلِي وَغَيْرَهُمْ ‏","","",""],[15678,15678,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏وَامْرَأَةٍ ‏ ‏مِنْ ‏ ‏قَيْسٍ ‏ ‏أَنَّهُمَا ‏ ‏سَمِعَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَحَدُهُمَا سَمِعْتُهُ يَقُولُ ‏ ‏اللَّهُمَّ اغْفِرْ لِي ذَنْبِي وَخَطَئِي وَعَمْدِي ‏ ‏و قَالَ ‏ ‏الْآخَرُ سَمِعْتُهُ يَقُولُ ‏ ‏اللَّهُمَّ ‏ ‏أَسْتَهْدِيكَ لِأَرْشَدِ أَمْرِي وَأَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي ‏","","",""],[15679,15679,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ اجْعَلْنِي إِمَامَ قَوْمِي فَقَالَ ‏ ‏أَنْتَ إِمَامُهُمْ وَاقْتَدِ بِأَضْعَفِهِمْ وَاتَّخِذْ مُؤَذِّنًا لَا يَأْخُذُ عَلَى أَذَانِهِ أَجْرًا ‏","","",""],[15680,15680,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ اجْعَلْنِي إِمَامَ قَوْمِي قَالَ ‏ ‏أَنْتَ إِمَامُهُمْ فَاقْتَدِ بِأَضْعَفِهِمْ وَاتَّخِذْ مُؤَذِّنًا لَا يَأْخُذُ عَلَى أَذَانِهِ أَجْرًا ‏","","",""],[15681,15681,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ اجْعَلْنِي إِمَامَ قَوْمِي قَالَ ‏ ‏أَنْتَ إِمَامُهُمْ وَاقْتَدِ بِأَضْعَفِهِمْ وَاتَّخِذْ مُؤَذِّنًا لَا يَأْخُذُ عَلَى أَذَانِهِ أَجْرًا ‏","","",""],[15682,15682,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏فَقَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الصِّيَامُ ‏ ‏جُنَّةٌ ‏ ‏كَجُنَّةِ ‏ ‏أَحَدِكُمْ مِنْ الْقِتَالِ وَكَانَ آخِرُ مَا ‏ ‏عَهِدَ ‏ ‏إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ بَعَثَنِي إِلَى ‏ ‏الطَّائِفِ ‏ ‏قَالَ يَا ‏ ‏عُثْمَانُ ‏ ‏تَجَوَّزْ ‏ ‏فِي الصَّلَاةِ فَإِنَّ فِي الْقَوْمِ الْكَبِيرَ وَذَا الْحَاجَةِ ‏","","",""],[15683,15683,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ خُصَيْفَةَ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏قَالَ ‏ ‏أَتَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِي وَجَعٌ قَدْ كَادَ يُهْلِكُنِي فَقَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏امْسَحْهُ بِيَمِينِكَ سَبْعَ مَرَّاتٍ وَقُلْ أَعُوذُ بِعِزَّةِ اللَّهِ وَقُدْرَتِهِ مِنْ شَرِّ مَا أَجِدُ ‏ ‏قَالَ ‏ ‏فَفَعَلْتُ ذَلِكَ فَأَذْهَبَ اللَّهُ مَا كَانَ بِي فَلَمْ أَزَلْ آمُرُ بِهِ أَهْلِي وَغَيْرَهُمْ ‏","","",""],[15684,15684,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏النُّعْمَانِ بْنِ سَالِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَشْيَاخَنَا ‏ ‏مِنْ ‏ ‏ثَقِيفٍ ‏ ‏قَالُوا أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ أَبِي الْعَاصِ ‏ ‏أَنَّهُ قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُمَّ قَوْمَكَ ‏ ‏وَإِذَا أَمَمْتَ قَوْمَكَ فَأَخِفَّ بِهِمْ الصَّلَاةَ فَإِنَّهُ يَقُومُ فِيهَا الصَّغِيرُ وَالْكَبِيرُ وَالضَّعِيفُ وَالْمَرِيضُ وَذُو الْحَاجَةِ ‏","","",""],[15685,15685,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ طَلْحَةَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عُثْمَانُ ‏ ‏أُمَّ قَوْمَكَ ‏ ‏وَمَنْ أَمَّ الْقَوْمَ فَلْيُخَفِّفْ ‏ ‏فَإِنَّ فِيهِمْ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ فَإِذَا صَلَّيْتَ لِنَفْسِكَ فَصَلِّ كَيْفَ شِئْتَ ‏","","",""],[15686,15686,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَعِيدَ بْنَ الْمُسَيِّبِ ‏ ‏قَالَ حَدَّثَ ‏ ‏عُثْمَانُ بْنُ أَبِي الْعَاصِ ‏ ‏قَالَ ‏ ‏آخِرُ مَا عَهِدَ إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَمَمْتَ قَوْمًا فَأَخِفَّ بِهِمْ الصَّلَاةَ ‏","","",""],[15687,15687,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي هِنْدٍ ‏ ‏أَنَّ ‏ ‏مُطَرِّفًا ‏ ‏مِنْ ‏ ‏بَنِي عَامِرِ بْنِ صَعْصَعَةَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ ‏ ‏عُثْمَانَ بْنَ أَبِي الْعَاصِ الثَّقَفِيَّ ‏ ‏دَعَا لَهُ بِلَبَنٍ لِيَسْقِيَهُ فَقَالَ ‏ ‏مُطَرِّفٌ ‏ ‏إِنِّي صَائِمٌ فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الصِّيَامُ ‏ ‏جُنَّةٌ ‏ ‏مِنْ النَّارِ ‏ ‏كَجُنَّةِ ‏ ‏أَحَدِكُمْ مِنْ الْقِتَالِ وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ صِيَامٌ حَسَنٌ صِيَامُ ثَلَاثَةِ أَيَّامٍ مِنْ الشَّهْرِ ‏","","",""],[15688,15688,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاصِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُنَادِي مُنَادٍ كُلَّ لَيْلَةٍ هَلْ مِنْ دَاعٍ فَيُسْتَجَابَ لَهُ هَلْ مِنْ سَائِلٍ ‏ ‏فَيُعْطَى هَلْ مِنْ مُسْتَغْفِرٍ فَيُغْفَرَ لَهُ حَتَّى ‏ ‏يَنْفَجِرَ ‏ ‏الْفَجْرُ ‏","","",""],[15689,15689,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏مَرَّ ‏ ‏عُثْمَانُ بْنُ أَبِي الْعَاصِ ‏ ‏عَلَى ‏ ‏كِلَابِ بْنِ أُمَيَّةَ ‏ ‏وَهُوَ جَالِسٌ عَلَى مَجْلِسِ ‏ ‏الْعَاشِرِ ‏ ‏بِالْبَصْرَةِ ‏ ‏فَقَالَ مَا يُجْلِسُكَ هَاهُنَا قَالَ اسْتَعْمَلَنِي هَذَا عَلَى هَذَا الْمَكَانِ ‏ ‏يَعْنِي ‏ ‏زِيَادًا ‏ ‏فَقَالَ لَهُ ‏ ‏عُثْمَانُ ‏ ‏أَلَا أُحَدِّثُكَ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَلَى فَقَالَ ‏ ‏عُثْمَانُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كَانَ ‏ ‏لِدَاوُدَ ‏ ‏نَبِيِّ اللَّهِ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏مِنْ اللَّيْلِ سَاعَةٌ يُوقِظُ فِيهَا أَهْلَهُ فَيَقُولُ يَا آلَ ‏ ‏دَاوُدَ ‏ ‏قُومُوا فَصَلُّوا فَإِنَّ هَذِهِ سَاعَةٌ يَسْتَجِيبُ اللَّهُ فِيهَا الدُّعَاءَ إِلَّا لِسَاحِرٍ أَوْ ‏ ‏عَشَّارٍ ‏ ‏فَرَكِبَ ‏ ‏كِلاَبُ بْنُ أُمَيَّةَ ‏ ‏سَفِينَتَهُ فَأَتَى ‏ ‏زَيِادًا ‏ ‏فَاسْتَعْفَاهُ فَأَعْفَاهُ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏مَرَّ ‏ ‏عُثْمَانُ بْنُ أَبِي الْعَاصِ ‏ ‏عَلَى ‏ ‏كِلَابِ بْنِ أُمَيَّةَ ‏ ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[15690,15690,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏أَوْ ‏ ‏بَدْرٍ ‏ ‏أَنَا أَشُكُّ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ عَلِيٍّ الْحَنَفِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَنْظُرُ اللَّهُ عَزَّ وَجَلَّ إِلَى صَلَاةِ عَبْدٍ لَا يُقِيمُ فِيهَا ‏ ‏صُلْبَهُ ‏ ‏بَيْنَ رُكُوعِهَا وَسُجُودِهَا ‏","","",""],[15691,15691,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ عُتْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَدْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَلِيِّ بْنِ شَيْبَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَنْظُرُ اللَّهُ عَزَّ وَجَلَّ إِلَى رَجُلٍ لَا يُقِيمُ ‏ ‏صُلْبَهُ ‏ ‏بَيْنَ رُكُوعِهِ وَسُجُودِهِ ‏","","",""],[15692,15692,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُلَازِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَدْرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصَّلَاةِ فِي الثَّوْبِ الْوَاحِدِ ‏ ‏فَأَطْلَقَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِزَارَهُ ‏ ‏فَطَارَقَ ‏ ‏بِهِ رِدَاءَهُ ثُمَّ قَامَ فَصَلَّى فَلَمَّا قَضَى الصَّلَاةَ قَالَ كُلُّكُمْ يَجِدُ ثَوْبَيْنِ ‏","","",""],[15693,15693,"","","‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ بْنُ عُتْبَةَ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَأَلَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيَتَوَضَّأُ أَحَدُنَا إِذَا مَسَّ ذَكَرَهُ قَالَ إِنَّمَا هُوَ ‏ ‏بَضْعَةٌ ‏ ‏مِنْكَ أَوْ جَسَدِكَ ‏","","",""],[15694,15694,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏عِيسَى بْنِ خُثَيْمٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏شَهِدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسَأَلَهُ رَجُلٌ عَنْ الصَّلَاةِ فِي الثَّوْبِ الْوَاحِدِ فَلَمْ يَقُلْ لَهُ شَيْئًا فَلَمَّا أُقِيمَتْ الصَّلَاةُ ‏ ‏طَارَقَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ثَوْبَيْهِ فَصَلَّى فِيهِمَا ‏","","",""],[15695,15695,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَحَدُكُمْ مِنْ امْرَأَتِهِ حَاجَةً ‏ ‏فَلْيَأْتِهَا ‏ ‏وَلَوْ كَانَتْ عَلَى ‏ ‏تَنُّورٍ ‏","","",""],[15696,15696,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَدْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَكُونُ ‏ ‏وِتْرَانِ ‏ ‏فِي لَيْلَةٍ ‏","","",""],[15697,15697,"","","‏ ‏قَالَ ‏ ‏وَسُئِلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الرَّجُلِ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ قَالَ وَكُلُّكُمْ يَجِدُ ثَوْبَيْنِ ‏","","",""],[15698,15698,"","","‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَيْتُمْ الْهِلَالَ فَصُومُوا وَإِذَا رَأَيْتُمُوهُ فَأَفْطِرُوا فَإِنْ أُغْمِيَ عَلَيْكُمْ فَأَتِمُّوا ‏ ‏الْعِدَّةَ ‏","","",""],[15699,15699,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ النُّعْمَانِ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيْسَ الْفَجْرُ الْمُسْتَطِيلَ فِي الْأُفُقِ وَلَكِنَّهُ ‏ ‏الْمُعْتَرِضُ ‏ ‏الْأَحْمَرُ ‏","","",""],[15700,15700,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ رَجُلٌ فَقَالَ مَسِسْتُ ذَكَرِي ‏ ‏أَوْ ‏ ‏الرَّجُلُ يَمَسُّ ذَكَرَهُ ‏ ‏فِي الصَّلَاةِ عَلَيْهِ الْوُضُوءُ قَالَ لَا إِنَّمَا هُوَ مِنْكَ ‏","","",""],[15701,15701,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَدْرٍ ‏ ‏عَنْ ‏ ‏طَلْقِ بْنِ عَلِيٍّ ‏ ‏قَالَ ‏ ‏وَفَدْنَا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا وَدَّعَنَا أَمَرَنِي فَأَتَيْتُهُ ‏ ‏بِإِدَاوَةٍ ‏ ‏مِنْ مَاءٍ ‏ ‏فَحَثَا ‏ ‏مِنْهَا ثُمَّ ‏ ‏مَجَّ ‏ ‏فِيهَا ثَلَاثًا ثُمَّ ‏ ‏أَوْكَأَهَا ‏ ‏ثُمَّ قَالَ ‏ ‏اذْهَبْ بِهَا ‏ ‏فَانْضَحْ ‏ ‏مَسْجِدَ قَوْمِكَ وَأْمُرْهُمْ يَرْفَعُوا بِرُءُوسِهِمْ أَنْ رَفَعَهَا اللَّهُ قُلْتُ إِنَّ الْأَرْضَ بَيْنَنَا وَبَيْنَكَ بَعِيدَةٌ وَإِنَّهَا ‏ ‏تَيْبَسُ ‏ ‏قَالَ فَإِذَا ‏ ‏يَبِسَتْ ‏ ‏فَمُدَّهَا ‏","","",""],[15702,15702,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ جَعَلَ هَذِهِ الْأَهِلَّةَ مَوَاقِيتَ لِلنَّاسِ ‏ ‏صُومُوا لِرُؤْيَتِهِ وَأَفْطِرُوا لِرُؤْيَتِهِ فَإِنْ ‏ ‏غُمَّ ‏ ‏عَلَيْكُمْ فَأَتِمُّوا ‏ ‏الْعِدَّةَ ‏","","",""],[15703,15703,"","","‏ ‏حَدَّثَنَا ‏ ‏قُرَّانُ بْنُ تَمَّامٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَجُلٌ يَا رَسُولَ اللَّهِ ‏ ‏أَيَتَوَضَّأُ أَحَدُنَا إِذَا مَسَّ ذَكَرَهُ فِي الصَّلَاةِ قَالَ هَلْ هُوَ إِلَّا مِنْكَ ‏ ‏أَوْ ‏ ‏بَضْعَةٌ ‏ ‏مِنْكَ ‏","","",""],[15704,15704,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُلَازِمُ بْنُ عَمْرٍو السُّحَيْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏جَدِّي ‏ ‏عَبْدُ اللَّهِ بْنُ بَدْرٍ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏سِرَاجُ بْنُ عُقْبَةَ ‏ ‏أَنَّ ‏ ‏قَيْسَ بْنَ طَلْقٍ ‏ ‏حَدَّثَهُمَا ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏طَلْقَ بْنَ عَلِيٍّ ‏ ‏أَتَانَا فِي رَمَضَانَ وَكَانَ عِنْدَنَا حَتَّى أَمْسَى فَصَلَّى بِنَا الْقِيَامَ فِي رَمَضَانَ ‏ ‏وَأَوْتَرَ ‏ ‏بِنَا ثُمَّ انْحَدَرَ إِلَى مَسْجِدِ ‏ ‏رَيْمَانَ ‏ ‏فَصَلَّى بِهِمْ حَتَّى بَقِيَ ‏ ‏الْوَتْرُ ‏ ‏فَقَدَّمَ رَجُلًا ‏ ‏فَأَوْتَرَ ‏ ‏بِهِمْ وَقَالَ سَمِعْتُ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا ‏ ‏وِتْرَانِ ‏ ‏فِي لَيْلَةٍ ‏","","",""],[15705,15705,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَبْلَ أَنْ يُمْتَحَنَ ‏ ‏عَنْ ‏ ‏مُلَازِمِ بْنِ عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏هَوْذَةُ بْنُ قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ الْأَيْسَرِ ‏","","",""],[15706,15706,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُلَازِمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سِرَاجُ بْنُ عُقْبَةَ ‏ ‏وَعَبْدُ اللَّهِ بْنُ بَدْرٍ ‏ ‏وَحَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جِئْتُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابُهُ يَبْنُونَ الْمَسْجِدَ قَالَ فَكَأَنَّهُ لَمْ يُعْجِبْهُ عَمَلُهُمْ قَالَ فَأَخَذْتُ الْمِسْحَاةَ فَخَلَطْتُ بِهَا الطِّينَ فَكَأَنَّهُ أَعْجَبَهُ أَخْذِي الْمِسْحَاةَ وَعَمَلِي فَقَالَ ‏ ‏دَعُوا ‏ ‏الْحَنَفِيَّ وَالطِّينَ فَإِنَّهُ أَضْبَطُكُمْ لِلطِّينِ ‏","","",""],[15707,15707,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُلَازِمُ بْنُ عَمْرٍو السُّحَيْمِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سِرَاجُ بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏خَلْدَةَ بِنْتِ طَلْقٍ ‏ ‏قَالَتْ حَدَّثَنَي ‏ ‏أَبِي طَلْقٌ ‏ ‏أَنَّهُ ‏ ‏كَانَ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَالِسًا فَجَاءَ ‏ ‏صَحَّارُ ‏ ‏عَبْدِ الْقَيْسِ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ مَا تَرَى فِي شَرَابٍ نَصْنَعُهُ بِأَرْضِنَا مِنْ ثِمَارِنَا فَأَعْرَضَ عَنْهُ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى سَأَلَهُ ثَلَاثَ مَرَّاتٍ حَتَّى قَامَ فَصَلَّى فَلَمَّا قَضَى صَلَاتَهُ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ سَائِلٌ عَنْ الْمُسْكِرِ لَا تَشْرَبُهُ وَلَا ‏ ‏تَسْقِيهِ أَخَاكَ الْمُسْلِمَ فَوَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏أَوْ كَالَّذِي يُحْلَفُ بِهِ ‏ ‏لَا يَشْرَبُهُ رَجُلٌ ابْتِغَاءَ لَذَّةِ سُكْرِهِ فَيَسْقِيَهُ اللَّهُ الْخَمْرَ يَوْمَ الْقِيَامَةِ ‏","","",""],[15708,15708,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُلَازِمُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَدْرٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَلِيٍّ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَاهُ ‏ ‏عَلِيَّ بْنَ شَيْبَانَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّهُ خَرَجَ وَافِدًا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَصَلَّيْنَا خَلْفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَحَ ‏ ‏بِمُؤْخِرِ عَيْنَيْهِ إِلَى رَجُلٍ لَا يُقِيمُ ‏ ‏صُلْبَهُ ‏ ‏فِي الرُّكُوعِ وَالسُّجُودِ فَلَمَّا انْصَرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَا مَعْشَرَ الْمُسْلِمِينَ إِنَّهُ ‏ ‏لَا صَلَاةَ لِمَنْ لَا يُقِيمُ ‏ ‏صُلْبَهُ ‏ ‏فِي الرُّكُوعِ وَالسُّجُودِ قَالَ وَرَأَى رَجُلًا ‏ ‏يُصَلِّي خَلْفَ الصَّفِّ فَوَقَفَ حَتَّى انْصَرَفَ الرَّجُلُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقْبِلْ صَلَاتَكَ فَلَا صَلَاةَ لِرَجُلٍ فَرْدٍ خَلْفَ الصَّفِّ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فَرْدًا خَلْفَ الصَّفِّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ الشَّقَرِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمْرُو بْنُ جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بَدْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَلِيِّ بْنِ شَيْبَانَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏فَذَكَرَهُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَيُّوبُ بْنُ عُتْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَدْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَلِيِّ بْنِ شَيْبَانَ السُّحَيْمِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏فَذَكَرَهُ ‏","","",""],[15709,15709,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُلَازِمُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ بَدْرٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ طَلْقٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏طَلْقِ بْنِ عَلِيٍّ ‏ ‏قَالَ قَالَ ‏ ‏لَدَغَتْنِي ‏ ‏عَقْرَبٌ عِنْدَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَقَانِي ‏ ‏وَمَسَحَهَا ‏","","",""],[15710,15710,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ سَرِيعٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏سَرِيَّةً ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏فَأَتَوْا حَيًّا مِنْ أَحْيَاءِ ‏ ‏الْعَرَبِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ وَالَّذِي نَفْسِي بِيَدِهِ ‏ ‏مَا مِنْ ‏ ‏نَسَمَةٍ ‏ ‏تُولَدُ إِلَّا عَلَى ‏ ‏الْفِطْرَةِ ‏ ‏حَتَّى يُعْرِبَ عَنْهَا لِسَانُهَا ‏","","",""],[15711,15711,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ سَرِيعٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِنِّي قَدْ مَدَحْتُ اللَّهَ بِمَدْحَةٍ وَمَدَحْتُكَ بِأُخْرَى فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَاتِ وَابْدَأْ بِمَدْحَةِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[15712,15712,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْأَحْنَفِ بْنِ قَيْسٍ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ سَرِيعٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْبَعَةٌ يَوْمَ الْقِيَامَةِ رَجُلٌ أَصَمُّ لَا يَسْمَعُ شَيْئًا وَرَجُلٌ أَحْمَقُ وَرَجُلٌ ‏ ‏هَرَمٌ ‏ ‏وَرَجُلٌ مَاتَ فِي ‏ ‏فَتْرَةٍ ‏ ‏فَأَمَّا الْأَصَمُّ فَيَقُولُ رَبِّ لَقَدْ جَاءَ الْإِسْلَامُ وَمَا أَسْمَعُ شَيْئًا وَأَمَّا الْأَحْمَقُ فَيَقُولُ رَبِّ لَقَدْ جَاءَ الْإِسْلَامُ وَالصِّبْيَانُ يَحْذِفُونِي بِالْبَعْرِ وَأَمَّا ‏ ‏الْهَرَمُ ‏ ‏فَيَقُولُ رَبِّي لَقَدْ جَاءَ الْإِسْلَامُ وَمَا أَعْقِلُ شَيْئًا وَأَمَّا الَّذِي مَاتَ فِي الْفَتْرَةِ فَيَقُولُ رَبِّ مَا أَتَانِي لَكَ رَسُولٌ فَيَأْخُذُ مَوَاثِيقَهُمْ لَيُطِيعُنَّهُ فَيُرْسِلُ إِلَيْهِمْ أَنْ ادْخُلُوا النَّارَ قَالَ فَوَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَوْ دَخَلُوهَا لَكَانَتْ عَلَيْهِمْ بَرْدًا وَسَلَامًا ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏مِثْلَ هَذَا غَيْرَ أَنَّهُ قَالَ فِي آخِرِهِ فَمَنْ دَخَلَهَا كَانَتْ عَلَيْهِ ‏ ‏بَرْدًا ‏ ‏وَسَلَامًا وَمَنْ لَمْ يَدْخُلْهَا يُسْحَبُ إِلَيْهَا ‏","","",""],[15713,15713,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏السَّرِيُّ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏الْأَسْوَدِ بْنِ سَرِيعٍ ‏ ‏وَكَانَ رَجُلًا مِنْ ‏ ‏بَنِي سَعْدٍ ‏ ‏قَالَ وَكَانَ أَوَّلَ مَنْ قَصَّ فِي هَذَا الْمَسْجِدِ ‏ ‏يَعْنِي الْمَسْجِدَ الْجَامِعَ ‏ ‏قَالَ ‏ ‏غَزَوْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعَ غَزَوَاتٍ قَالَ فَتَنَاوَلَ قَوْمٌ الذُّرِّيَّةَ بَعْدَمَا قَتَلُوا الْمُقَاتِلَةَ فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَلَا مَا بَالُ أَقْوَامٍ قَتَلُوا الْمُقَاتِلَةَ حَتَّى تَنَاوَلُوا الذُّرِّيَّةَ قَالَ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَوَلَيْسَ أَبْنَاءُ الْمُشْرِكِينَ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ خِيَارَكُمْ أَبْنَاءُ الْمُشْرِكِينَ إِنَّهَا لَيْسَتْ ‏ ‏نَسَمَةٌ ‏ ‏تُولَدُ إِلَّا وُلِدَتْ عَلَى ‏ ‏الْفِطْرَةِ ‏ ‏فَمَا تَزَالُ عَلَيْهَا حَتَّى يُبِينَ عَنْهَا لِسَانُهَا فَأَبَوَاهَا يُهَوِّدَانِهَا أَوْ يُنَصِّرَانِهَا ‏ ‏قَالَ ‏ ‏وَأَخْفَاهَا ‏ ‏الْحَسَنُ ‏","","",""],[15714,15714,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَبَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏أَخْبَرَنِي قَالَ سَمِعْتُ ‏ ‏مُطَرِّفًا ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَوْمِ الدَّهْرِ قَالَ ‏ ‏مَا صَامَ وَمَا أَفْطَرَ ‏ ‏أَوْ لَا صَامَ وَلَا أَفْطَرَ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ لَا صَامَ وَلَا أَفْطَرَ ‏","","",""],[15715,15715,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا انْتَهَى إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ ‏ ‏وَقَالَ ‏ ‏وَكِيعٌ ‏ ‏مَرَّةً انْتَهَى إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقْرَأُ ‏ { ‏أَلْهَاكُمْ التَّكَاثُرُ حَتَّى زُرْتُمْ الْمَقَابِرَ ‏} ‏قَالَ ‏ ‏يَقُولُ ابْنُ ‏ ‏آدَمَ ‏ ‏مَالِي مَالِي وَهَلْ لَكَ مِنْ مَالِكَ إِلَّا مَا تَصَدَّقْتَ فَأَمْضَيْتَ أَوْ لَبِسْتَ فَأَبْلَيْتَ أَوْ أَكَلْتَ فَأَفْنَيْتَ ‏","","",""],[15716,15716,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏انْتَهَيْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقُولُ ‏ ‏أَلْهَاكُمْ التَّكَاثُرُ ‏ ‏يَقُولُ ابْنُ ‏ ‏آدَمَ ‏ ‏مَالِي مَالِي وَمَا لَكَ مِنْ مَالِكَ إِلَّا مَا أَكَلْتَ فَأَفْنَيْتَ أَوْ لَبِسْتَ فَأَبْلَيْتَ أَوْ تَصَدَّقْتَ فَأَمْضَيْتَ ‏","","",""],[15717,15717,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُطَرِّفَ بْنَ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَنْتَ سَيِّدُ ‏ ‏قُرَيْشٍ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّيِّدُ اللَّهُ قَالَ أَنْتَ أَفْضَلُهَا ‏ ‏فِيهَا قَوْلًا وَأَعْظَمُهَا فِيهَا ‏ ‏طَوْلًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَقُلْ أَحَدُكُمْ بِقَوْلِهِ وَلَا ‏ ‏يَسْتَجِرُّهُ ‏ ‏الشَّيْطَانُ ‏","","",""],[15718,15718,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَسُئِلَ عَنْ رَجُلٍ يَصُومُ الدَّهْرَ قَالَ لَا صَامَ وَلَا أَفْطَرَ ‏","","",""],[15719,15719,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي نَعْلَيْهِ ‏","","",""],[15720,15720,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي ثُمَّ ‏ ‏يَتَنَخَّمُ ‏ ‏تَحْتَ قَدَمِهِ ثُمَّ دَلَكَهَا بِنَعْلِهِ وَهِيَ فِي رِجْلِهِ ‏","","",""],[15721,15721,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُوَيْدُ بْنُ عَمْرٍو ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مَهْدِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏غَيْلَانُ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ وَفَدَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏رَهْطٍ ‏ ‏مِنْ ‏ ‏بَنِي عَامِرٍ ‏ ‏قَالَ فَأَتَيْنَاهُ فَسَلَّمْنَا عَلَيْهِ فَقُلْنَا ‏ ‏أَنْتَ وَلِيُّنَا وَأَنْتَ سَيِّدُنَا وَأَنْتَ ‏ ‏أَطْوَلُ ‏ ‏عَلَيْنَا ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏وَأَنْتَ ‏ ‏أَطْوَلُ ‏ ‏عَلَيْنَا ‏ ‏طَوْلًا ‏ ‏وَأَنْتَ أَفْضَلُنَا عَلَيْنَا فَضْلًا وَأَنْتَ ‏ ‏الْجَفْنَةُ ‏ ‏الْغَرَّاءُ ‏ ‏فَقَالَ قُولُوا قَوْلَكُمْ وَلَا ‏ ‏يَسْتَجِرَّنَّكُمْ ‏ ‏الشَّيْطَانُ قَالَ ‏ ‏وَرُبَّمَا قَالَ وَلَا ‏ ‏يَسْتَهْوِيَنَّكُمْ ‏","","",""],[15722,15722,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ الْبُنَانِيِّ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِي صَدْرِهِ ‏ ‏أَزِيزٌ ‏ ‏كَأَزِيزِ ‏ ‏الْمِرْجَلِ ‏ ‏مِنْ الْبُكَاءِ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏لَمْ يَقُلْ مِنْ الْبُكَاءِ إِلَّا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏","","",""],[15723,15723,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏صَلَّى مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَنَخَّعَ فَدَلَكَهَا بِنَعْلِهِ الْيُسْرَى ‏","","",""],[15724,15724,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدٌ يَعْنِي الطَّوِيلَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا قَالَ يَا رَسُولَ اللَّهِ ‏ ‏هَوَامَّ الْإِبِلِ نُصِيبُهَا قَالَ ‏ ‏ضَالَّةُ ‏ ‏الْمُسْلِمِ حَرَقُ النَّارِ ‏","","",""],[15725,15725,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَامَ الدَّهْرَ لَا صَامَ وَلَا أَفْطَرَ وَمَا صَامَ وَلَا أَفْطَرَ ‏","","",""],[15726,15726,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُطَرِّفًا ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ أَنْتَ سَيِّدُ ‏ ‏قُرَيْشٍ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏السَّيِّدُ اللَّهُ فَقَالَ أَنْتَ أَفْضَلُهَا فِيهَا قَوْلًا وَأَعْظَمُهَا فِيهَا ‏ ‏طَوْلًا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَقُلْ أَحَدُكُمْ بِقَوْلِهِ وَلَا ‏ ‏يَسْتَجِرَّنَّهُ ‏ ‏الشَّيْطَانُ ‏ ‏أَوْ الشَّيَاطِينُ ‏","","",""],[15727,15727,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏انْتَهَيْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي وَلِصَدْرِهِ ‏ ‏أَزِيزٌ ‏ ‏كَأَزِيزِ ‏ ‏الْمِرْجَلِ ‏","","",""],[15728,15728,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ صَوْمِ الدَّهْرِ فَقَالَ النَّبِيُّ ‏ ‏لَا صَامَ وَلَا أَفْطَرَ ‏ ‏أَوْ قَالَ لَمْ يَصُمْ وَلَمْ يُفْطِرْ ‏","","",""],[15729,15729,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَخْبَرَنِي ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي نَعْلَيْهِ قَالَ ‏ ‏فَتَنَخَّعَ ‏ ‏فَتَفَلَهُ تَحْتَ نَعْلِهِ الْيُسْرَى قَالَ ثُمَّ رَأَيْتُهُ حَكَّهَا بِنَعْلَيْهِ ‏","","",""],[15730,15730,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ‏ ‏سُئِلَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ رَجُلٍ يَصُومُ الدَّهْرَ فَقَالَ لَا صَامَ وَلَا أَفْطَرَ ‏","","",""],[15731,15731,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي فَبَزَقَ تَحْتَ قَدَمِهِ الْيُسْرَى ‏","","",""],[15732,15732,"","","‏ ‏قَالَ ‏ ‏أَنْبَأَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيَقُولُ ابْنُ ‏ ‏آدَمَ ‏ ‏مَالِي مَالِي وَهَلْ لَكَ مِنْ مَالِكَ إِلَّا مَا أَكَلْتَ فَأَفْنَيْتَ أَوْ لَبِسْتَ ‏ ‏فَأَبْلَيْتَ ‏ ‏أَوْ تَصَدَّقْتَ ‏ ‏فَأَمْضَيْتَ ‏","","",""],[15733,15733,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَكَانَ أَبُوهُ قَدْ أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ الدَّهْرَ فَلَا صَامَ وَلَا أَفْطَرَ ‏","","",""],[15734,15734,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏مُطَرِّفُ بْنُ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏دُفِعْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقْرَأُ هَذِهِ السُّورَةَ ‏ ‏أَلْهَاكُمْ التَّكَاثُرُ ‏ ‏فَذَكَرَ مِثْلَهُ سَوَاءً وَلَيْسَ فِيهِ قَوْلُ ‏ ‏قَتَادَةَ ‏ ‏يَعْنِي مِثْلَ حَدِيثِ ‏ ‏هَمَّامٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ أَبِي شَيْبَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ سَعِيدٍ أَبِي طَلْحَةَ الرَّاسِبِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏غَيْلَانُ بْنُ جَرِيرٍ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي قَاعِدًا ‏ ‏أَوْ قَائِمًا ‏ ‏وَهُوَ يَقْرَأُ ‏ ‏أَلْهَاكُمْ التَّكَاثُرُ ‏ ‏حَتَّى خَتَمَهَا ‏","","",""],[15735,15735,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي وَلِصَدْرِهِ ‏ ‏أَزِيزٌ ‏ ‏كَأَزِيزِ ‏ ‏الْمِرْجَلِ ‏","","",""],[15736,15736,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَقْرَأُ ‏ ‏أَلْهَاكُمْ التَّكَاثُرُ حَتَّى زُرْتُمْ الْمَقَابِرَ ‏ ‏قَالَ فَقَالَ ‏ ‏يَقُولُ ابْنُ ‏ ‏آدَمَ ‏ ‏مَالِي مَالِي وَهَلْ لَكَ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏مِنْ مَالِكَ إِلَّا مَا أَكَلْتَ فَأَفْنَيْتَ أَوْ لَبِسْتَ ‏ ‏فَأَبْلَيْتَ ‏ ‏أَوْ تَصَدَّقْتَ ‏ ‏فَأَمْضَيْتَ ‏ ‏وَكَانَ ‏ ‏قَتَادَةُ ‏ ‏يَقُولُ ‏ ‏كُلُّ صَدَقَةٍ لَمْ تُقْبَضْ فَلَيْسَ بِشَيْءٍ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏دَخَلَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعَهُ يَقُولُ فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏عَفَّانَ ‏ ‏وَلَمْ يَذْكُرْ قَوْلَ ‏ ‏قَتَادَةَ ‏","","",""],[15737,15737,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ يَعْنِي ابْنَ عُرْوَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏فِي بَيْتِ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فِي ثَوْبٍ قَدْ أَلْقَى طَرَفَيْهِ عَلَى ‏ ‏عَاتِقِهِ ‏ ‏فِي بَيْتِ ‏ ‏أُمِّ سَلَمَةَ ‏","","",""],[15738,15738,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏وَإِبْرَاهِيمُ بْنُ إِسْمَاعِيلَ ‏ ‏عَنْ ‏ ‏أَبِي وَجْزَةَ السَّعْدِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏مُزَيْنَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِطَعَامٍ فَقَالَ يَا ‏ ‏عُمَرُ ‏ ‏قَالَ ‏ ‏هِشَامٌ ‏ ‏يَا بُنَيَّ ‏ ‏سَمِّ اللَّهَ عَزَّ وَجَلَّ وَكُلْ بِيَمِينِكَ وَكُلْ مِمَّا يَلِيكَ ‏ ‏قَالَ ‏ ‏فَمَا زَالَتْ أُكْلَتِي بَعْدُ ‏","","",""],[15739,15739,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِي وَجْزَةَ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي سَعْدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي مُزَيْنَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا بُنَيَّ ‏ ‏إِذَا أَكَلْتَ فَسَمِّ اللَّهَ وَكُلْ بِيَمِينِكَ وَكُلْ مِمَّا يَلِيكَ ‏ ‏قَالَ ‏ ‏فَمَا زَالَتْ أُكْلَتِي بَعْدُ ‏","","",""],[15740,15740,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏وَهْبِ بْنِ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏قَالَ لِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا غُلَامُ ‏ ‏سَمِّ اللَّهَ وَكُلْ بِيَمِينِكَ وَكُلْ مِمَّا يَلِيكَ ‏ ‏فَلَمْ تَزَلْ تِلْكَ طُعْمَتِي بَعْدُ وَكَانَتْ يَدِي ‏ ‏تَطِيشُ ‏","","",""],[15741,15741,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي بَيْتِ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فِي ثَوْبٍ وَاحِدٍ ‏ ‏مُشْتَمِلًا ‏ ‏بِهِ ‏","","",""],[15742,15742,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِّ اللَّهَ ‏ ‏وَكُلْ بِيَمِينِكَ وَكُلْ مِمَّا يَلِيكَ ‏","","",""],[15743,15743,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏اللَّيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ قَدْ ‏ ‏خَالَفَ ‏ ‏بَيْنَ طَرَفَيْهِ جَعَلَ طَرَفَيْهِ عَلَى ‏ ‏عَاتِقَيْهِ ‏","","",""],[15744,15744,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ وَذَكَرَ ‏ ‏يَحْيَى بْنُ سَعِيدِ بْنِ قَيْسٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏قَدْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي ثَوْبٍ وَاحِدٍ ‏ ‏مُتَوَشِّحًا ‏ ‏بِهِ ‏","","",""],[15745,15745,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَعْدٍ الْمُقْعَدِ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏قُرِّبَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَعَامٌ فَقَالَ لِأَصْحَابِهِ ‏ ‏اذْكُرُوا اسْمَ اللَّهِ وَلْيَأْكُلْ كُلُّ امْرِئٍ مِمَّا يَلِيهِ ‏ ‏إِذَا قَالَ ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏وَذَكَرَ لَمْ يَسْمَعْهُ يَدُلُّ عَلَى صِدْقِهِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى أَبِي ‏ ‏حَدَّثَكُمْ ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو وَجْزَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏يَا بُنَيَّ ‏ ‏ادْنُهْ ‏ ‏وَسَمِّ اللَّهَ وَكُلْ مِمَّا يَلِيكَ ‏","","",""],[15746,15746,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏أَبِي مُوسَى بْنُ دَاوُدَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي وَجْزَةَ السَّعْدِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏دَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِطَعَامٍ يَأْكُلُهُ فَقَالَ ‏ ‏ادْنُ ‏ ‏فَسَمِّ اللَّهَ عَزَّ وَجَلَّ وَكُلْ بِيَمِينِكَ وَكُلْ مِمَّا يَلِيكَ ‏","","",""],[15747,15747,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى أَبِي ‏ ‏: ‏ ‏مَنْصُورُ بْنُ سَلَمَةَ الْخُزَاعِيُّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَوْ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو وَجْزَةَ السَّعْدِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عُمَرَ بْنَ أَبِي سَلَمَةَ رَبِيبَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏دَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏ادْنُ يَا بُنَيَّ فَسَمِّ وَكُلْ مِمَّا يَلِيكَ ‏ ‏حَدَّثَنَا ‏ ‏لُوَيْنٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ بِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي وَجْزَةَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[15748,15748,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي أُمَيَّةَ الْمَخْزُومِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي بَيْتِ ‏ ‏أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ثَوْبٍ وَاحِدٍ ‏ ‏مُتَوَشِّحًا ‏ ‏مَا عَلَيْهِ غَيْرُهُ ‏","","",""],[15749,15749,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ أَبِي الزِّنَادِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّهُ قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي أُمَيَّةَ ‏ ‏أَنَّهُ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي بَيْتِ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏فِي ثَوْبٍ ‏ ‏مُلْتَحِفًا ‏ ‏بِهِ ‏ ‏مُخَالِفًا ‏ ‏بَيْنَ طَرَفَيْهِ ‏","","",""],[15750,15750,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏أَنَّ ‏ ‏أَبَا سَلَمَةَ ‏ ‏حَدَّثَهُمْ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَصَابَتْ أَحَدَكُمْ مُصِيبَةٌ فَلْيَقُلْ ‏ { ‏إِنَّا لِلَّهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ ‏} ‏اللَّهُمَّ عِنْدَكَ ‏ ‏أَحْتَسِبُ ‏ ‏مُصِيبَتِي فَأْجُرْنِي فِيهَا وَأَبْدِلْنِي بِهَا خَيْرًا مِنْهَا ‏ ‏فَلَمَّا ‏ ‏قُبِضَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏خَلَفَنِي اللَّهُ عَزَّ وَجَلَّ فِي أَهْلِي خَيْرًا مِنْهُ ‏","","",""],[15751,15751,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ أُسَامَةَ بْنِ الْهَادِ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏الْمُطَّلِبِ ‏ ‏عَنْ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏أَتَانِي ‏ ‏أَبُو سَلَمَةَ ‏ ‏يَوْمًا مِنْ عِنْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَقَدْ سَمِعْتُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَوْلًا فَسُرِرْتُ بِهِ قَالَ ‏ ‏لَا تُصِيبُ أَحَدًا مِنْ الْمُسْلِمِينَ مُصِيبَةٌ ‏ ‏فَيَسْتَرْجِعَ ‏ ‏عِنْدَ مُصِيبَتِهِ ثُمَّ يَقُولُ اللَّهُمَّ ‏ ‏أْجُرْنِي ‏ ‏فِي مُصِيبَتِي وَاخْلُفْ لِي خَيْرًا مِنْهَا إِلَّا فُعِلَ ذَلِكَ بِهِ قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏فَحَفِظْتُ ذَلِكَ مِنْهُ فَلَمَّا تُوُفِّيَ ‏ ‏أَبُو سَلَمَةَ ‏ ‏اسْتَرْجَعْتُ ‏ ‏وَقُلْتُ اللَّهُمَّ ‏ ‏أْجُرْنِي ‏ ‏فِي مُصِيبَتِي وَاخْلُفْنِي خَيْرًا مِنْهُ ثُمَّ رَجَعْتُ إِلَى نَفْسِي قُلْتُ مِنْ أَيْنَ لِي خَيْرٌ مِنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏فَلَمَّا انْقَضَتْ عِدَّتِي اسْتَأْذَنَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏أَدْبُغُ ‏ ‏إِهَابًا ‏ ‏لِي فَغَسَلْتُ يَدَيَّ مِنْ ‏ ‏الْقَرَظِ ‏ ‏وَأَذِنْتُ لَهُ فَوَضَعْتُ لَهُ وِسَادَةَ ‏ ‏أَدَمٍ ‏ ‏حَشْوُهَا لِيفٌ فَقَعَدَ عَلَيْهَا فَخَطَبَنِي إِلَى نَفْسِي فَلَمَّا فَرَغَ مِنْ مَقَالَتِهِ قُلْتُ يَا رَسُولَ اللَّهِ مَا بِي أَنْ لَا تَكُونَ بِكَ الرَّغْبَةُ فِيَّ وَلَكِنِّي امْرَأَةٌ فِيَّ غَيْرَةٌ شَدِيدَةٌ فَأَخَافُ أَنْ ‏ ‏تَرَى مِنِّي شَيْئًا يُعَذِّبُنِي اللَّهُ بِهِ وَأَنَا امْرَأَةٌ دَخَلْتُ فِي السِّنِّ وَأَنَا ذَاتُ عِيَالٍ فَقَالَ أَمَّا مَا ذَكَرْتِ مِنْ الْغَيْرَةِ فَسَوْفَ يُذْهِبُهَا اللَّهُ عَزَّ وَجَلَّ مِنْكِ وَأَمَّا مَا ذَكَرْتِ مِنْ السِّنِّ فَقَدْ أَصَابَنِي مِثْلُ الَّذِي أَصَابَكِ وَأَمَّا مَا ذَكَرْتِ مِنْ الْعِيَالِ فَإِنَّمَا عِيَالُكِ عِيَالِي قَالَتْ فَقَدْ سَلَّمْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَزَوَّجَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏فَقَدْ أَبْدَلَنِي اللَّهُ ‏ ‏بِأَبِي سَلَمَةَ ‏ ‏خَيْرًا مِنْهُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15752,15752,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏وهَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بُكَيْرٌ يَعْنِي ابْنَ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ صَاحِبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَدْخُلُ الْمَلَائِكَةُ بَيْتًا فِيهِ صُورَةٌ ‏ ‏قَالَ ‏ ‏بُسْرٌ ‏ ‏ثُمَّ ‏ ‏اشْتَكَى ‏ ‏فَعُدْنَاهُ فَإِذَا عَلَى بَابِهِ سِتْرٌ فِيهِ صُورَةٌ فَقُلْتُ ‏ ‏لِعُبَيْدِ اللَّهِ الْخَوْلَانِيِّ ‏ ‏رَبِيبِ ‏ ‏مَيْمُونَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ يُخْبِرْنَا وَيَذْكُرْ الصُّوَرَ يَوْمَ الْأَوَّلِ ‏ ‏فَقَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَلَمْ تَسْمَعْهُ يَقُولُ قَالَ إِلَّا رَقْمٌ فِي ثَوْبٍ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏أَلَمْ ‏ ‏يُخْبِرْنَا ‏ ‏زَيْدٌ ‏ ‏عَنْ الصُّوَرِ يَوْمَ الْأَوَّلِ ‏ ‏فَقَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏أَلَمْ تَسْمَعْهُ حِينَ قَالَ إِلَّا رَقْمٌ فِي ثَوْبٍ ‏ ‏وَكَذَا ‏ ‏قَالَ ‏ ‏يُونُسُ ‏","","",""],[15753,15753,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَابْنُ أَبِي زَائِدَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو طَلْحَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ بَيْنَ الْحَجِّ وَالْعُمْرَةِ ‏","","",""],[15754,15754,"","","‏ ‏و قَالَ ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ابْنَ عَبَّاسٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أَبَا طَلْحَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تَدْخُلُ الْمَلَائِكَةُ بَيْتًا فِيهِ كَلْبٌ وَلَا صُورَةُ تَمَاثِيلَ ‏","","",""],[15755,15755,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏قَالَ ‏ ‏لَمَّا صَبَّحَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏ ‏وَقَدْ أَخَذُوا ‏ ‏مَسَاحِيَهُمْ ‏ ‏وَغَدَوْا إِلَى ‏ ‏حُرُوثِهِمْ وَأَرْضِهِمْ فَلَمَّا رَأَوْا نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهُ الْجَيْشُ رَكَضُوا ‏ ‏مُدْبِرِينَ ‏ ‏فَقَالَ نَبِيُّ اللَّهِ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ إِنَّا إِذَا نَزَلْنَا ‏ ‏بِسَاحَةِ ‏ ‏قَوْمٍ ‏ ‏فَسَاءَ ‏ ‏صَبَاحُ الْمُنْذَرِينَ ‏","","",""],[15756,15756,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِمَطَرٍ الْوَرَّاقِ ‏ ‏وَأَنَا عِنْدَهُ عَمَّنْ كَانَ يَأْخُذُ ‏ ‏الْحَسَنُ ‏ ‏أَنَّهُ ‏ ‏يَتَوَضَّأُ مِمَّا غَيَّرَتْ النَّارُ ‏ ‏قَالَ ‏ ‏أَخَذَهُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏وَأَخَذَهُ ‏ ‏أَنَسٌ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏وَأَخَذَهُ ‏ ‏أَبُو طَلْحَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15757,15757,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ حَفْصٍ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ آخَرَ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا غَيَّرَتْ النَّارُ ‏ ‏و قَالَ ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ حَفْصٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏ابْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏ ‏فَقَالَ ‏ ‏وَثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[15758,15758,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏فِي تَفْسِيرِ ‏ ‏شَيْبَانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏قَالَ ‏ ‏صَبَّحَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏ ‏وَقَدْ أَخَذُوا ‏ ‏مَسَاحِيَهُمْ ‏ ‏وَغَدَوْا إِلَى ‏ ‏حُرُوثِهِمْ فَلَمَّا رَأَوْا نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهُ الْجَيْشُ ‏ ‏نَكَصُوا ‏ ‏مُدْبِرِينَ ‏ ‏فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ خَرِبَتْ ‏ ‏خَيْبَرُ ‏ ‏إِنَّا إِذَا نَزَلْنَا ‏ ‏بِسَاحَةِ ‏ ‏قَوْمٍ ‏ ‏فَسَاءَ ‏ ‏صَبَاحُ الْمُنْذَرِينَ قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَوْلَهُ عَزَّ وَجَلَّ ‏ { ‏فَإِذَا نَزَلَ بِسَاحَتِهِمْ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ ‏} ‏قَالَ حَدَّثَ ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏قَالَ ‏ ‏صَبَّحَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[15759,15759,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ كَعْبِ بْنِ عُجْرَةَ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏أَصْبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا ‏ ‏طَيِّبَ ‏ ‏النَّفْسِ يُرَى فِي وَجْهِهِ ‏ ‏الْبِشْرُ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ أَصْبَحْتَ الْيَوْمَ ‏ ‏طَيِّبَ ‏ ‏النَّفْسِ يُرَى فِي وَجْهِكَ ‏ ‏الْبِشْرُ ‏ ‏قَالَ أَجَلْ ‏ ‏أَتَانِي آتٍ مِنْ رَبِّي عَزَّ وَجَلَّ فَقَالَ مَنْ صَلَّى عَلَيْكَ مِنْ أُمَّتِكَ صَلَاةً كَتَبَ اللَّهُ لَهُ عَشْرَ حَسَنَاتٍ وَمَحَا عَنْهُ عَشْرَ سَيِّئَاتٍ وَرَفَعَ لَهُ عَشْرَ دَرَجَاتٍ وَرَدَّ عَلَيْهِ مِثْلَهَا ‏","","",""],[15760,15760,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ بْنُ عُيَيْنَةَ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏يَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَدْخُلُ الْمَلَائِكَةُ بَيْتًا فِيهِ صُورَةٌ وَلَا كَلْبٌ ‏","","",""],[15761,15761,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ زَكَرِيَّا بْنِ أَبِي زَائِدَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ أَنْبَأَنِي ‏ ‏أَبُو طَلْحَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ بَيْنَ حَجَّةٍ وَعُمْرَةٍ ‏","","",""],[15762,15762,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ مُعَاذٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا ‏ ‏غَلَبَ ‏ ‏قَوْمًا أَحَبَّ أَنْ يُقِيمَ ‏ ‏بِعَرْصَتِهِمْ ‏ ‏ثَلَاثًا ‏","","",""],[15763,15763,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَطَاءٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا قَاتَلَ قَوْمًا فَهَزَمَهُمْ أَقَامَ ‏ ‏بِالْعَرْصَةِ ‏ ‏ثَلَاثًا وَإِنَّهُ لَمَّا كَانَ يَوْمُ ‏ ‏بَدْرٍ ‏ ‏أَمَرَ ‏ ‏بِصَنَادِيدِ ‏ ‏قُرَيْشٍ ‏ ‏فَأُلْقُوا فِي ‏ ‏قَلِيبٍ ‏ ‏مِنْ ‏ ‏قُلُبِ ‏ ‏بَدْرٍ ‏ ‏خَبِيثٍ مُنْتِنٍ قَالَ ثُمَّ رَاحَ إِلَيْهِمْ وَرُحْنَا مَعَهُ ثُمَّ قَالَ يَا ‏ ‏أَبَا جَهْلِ بْنَ هِشَامٍ ‏ ‏وَيَا ‏ ‏عُتْبَةَ بْنَ رَبِيعَةَ ‏ ‏وَيَا ‏ ‏شَيْبَةَ بْنَ رَبِيعَةَ ‏ ‏وَيَا ‏ ‏وَلِيدَ بْنَ عُتْبَةَ ‏ ‏هَلْ وَجَدْتُمْ مَا وَعَدَكُمْ رَبُّكُمْ حَقًّا فَإِنِّي قَدْ وَجَدْتُ مَا وَعَدَنِي رَبِّي حَقًّا قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ أَتُكَلِّمُ أَجْسَادًا لَا أَرْوَاحَ فِيهَا قَالَ وَالَّذِي بَعَثَنِي بِالْحَقِّ مَا أَنْتُمْ بِأَسْمَعَ لِمَا أَقُولُ مِنْهُمْ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏بَعَثَهُمْ اللَّهُ عَزَّ وَجَلَّ لِيَسْمَعُوا كَلَامَهُ تَوْبِيخًا وَصَغَارًا ‏ ‏وَتَقْمِئَةً ‏ ‏قَالَ فِي أَوَّلِ الْحَدِيثِ لَمَّا فَرَغَ مِنْ أَهْلِ ‏ ‏بَدْرٍ ‏ ‏أَقَامَ ‏ ‏بِالْعَرْصَةِ ‏ ‏ثَلَاثًا ‏","","",""],[15764,15764,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏وَحُسَيْنٌ ‏ ‏فِي تَفْسِيرِ ‏ ‏شَيْبَانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ وَحَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أَبَا طَلْحَةَ ‏ ‏قَالَ ‏ ‏غَشِيَنَا ‏ ‏النُّعَاسُ وَنَحْنُ فِي ‏ ‏مَصَافِّنَا ‏ ‏يَوْمَ ‏ ‏بَدْرٍ ‏ ‏قَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏وَكُنْتُ فِيمَنْ ‏ ‏غَشِيَهُ ‏ ‏النُّعَاسُ يَوْمَئِذٍ فَجَعَلَ سَيْفِي يَسْقُطُ مِنْ يَدِي وَآخُذُهُ وَيَسْقُطُ وَآخُذُهُ ‏","","",""],[15765,15765,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏قَالَ ‏ ‏لَمَّا صَبَّحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَيْبَرَ ‏ ‏وَقَدْ أَخَذُوا ‏ ‏مَسَاحِيَهُمْ ‏ ‏وَغَدَوْا إِلَى ‏ ‏حُرُوثِهِمْ وَأَرْضِيهِمْ فَلَمَّا رَأَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهُ الْجَيْشُ ‏ ‏نَكَصُوا ‏ ‏مُدْبِرِينَ ‏ ‏فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ إِنَّا إِذَا نَزَلْنَا ‏ ‏بِسَاحَةِ ‏ ‏قَوْمٍ ‏ { ‏فَسَاءَ ‏ ‏صَبَاحُ الْمُنْذَرِينَ ‏}","","",""],[15766,15766,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ذَكَرَ ‏ ‏لَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏بِأَرْبَعَةٍ وَعِشْرِينَ رَجُلًا مِنْ ‏ ‏صَنَادِيدِ ‏ ‏قُرَيْشٍ ‏ ‏فَقُذِفُوا فِي ‏ ‏طَوِيٍّ ‏ ‏مِنْ ‏ ‏أَطْوَاءِ ‏ ‏بَدْرٍ ‏ ‏خَبِيثٍ ‏ ‏مُخْبِثٍ وَكَانَ إِذَا ‏ ‏ظَهَرَ ‏ ‏عَلَى قَوْمٍ أَقَامَ ‏ ‏بِالْعَرْصَةِ ‏ ‏ثَلَاثَ لَيَالٍ فَلَمَّا كَانَ ‏ ‏بِبَدْرٍ ‏ ‏الْيَوْمَ الثَّالِثَ أَمَرَ بِرَاحِلَتِهِ فَشُدَّ عَلَيْهَا رَحْلُهَا ثُمَّ مَشَى وَاتَّبَعَهُ أَصْحَابُهُ فَقَالَ مَا ‏ ‏نُرَاهُ إِلَّا يَنْطَلِقُ لِيَقْضِيَ حَاجَتَهُ حَتَّى قَامَ عَلَى شَفَةِ ‏ ‏الرَّكِيِّ ‏ ‏فَجَعَلَ يُنَادِيهِمْ بِأَسْمَائِهِمْ وَأَسْمَاءِ آبَائِهِمْ يَا فُلَانُ بْنَ فُلَانٍ وَيَا فُلَانُ بْنَ فُلَانٍ أَيَسُرُّكُمْ أَنَّكُمْ أَطَعْتُمْ اللَّهَ وَرَسُولَهُ فَإِنَّا قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّا فَهَلْ وَجَدْتُمْ مَا وَعَدَ رَبُّكُمْ حَقًّا فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ مَا تُكَلِّمُ مِنْ أَجْسَادٍ لَا أَرْوَاحَ لَهَا فَقَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ مَا أَنْتُمْ بِأَسْمَعَ لِمَا أَقُولُ مِنْهُمْ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏أَحْيَاهُمْ اللَّهُ حَتَّى أَسْمَعَهُمْ قَوْلَهُ تَوْبِيخًا وَتَصْغِيرًا ‏ ‏وَتَقْمِئَةً ‏ ‏وَحَسْرَةً وَنَدَامَةً ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏عَنْ ‏ ‏شَيْبَانَ ‏ ‏وَلَمْ يُسْنِدْهُ عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏قَالَ ‏ ‏وَتَقْمِئَةً ‏","","",""],[15767,15767,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏سُلَيْمَانُ ‏ ‏مَوْلًى ‏ ‏لِلْحَسَنِ بْنِ عَلِيٍّ ‏ ‏زَمَنَ ‏ ‏الْحَجَّاحِ ‏ ‏فَحَدَّثَنَا عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ ذَاتَ يَوْمٍ ‏ ‏وَالْبِشْرُ ‏ ‏يُرَى فِي وَجْهِهِ فَقُلْنَا إِنَّا ‏ ‏لَنَرَى ‏ ‏الْبِشْرَ ‏ ‏فِي وَجْهِكَ فَقَالَ إِنَّهُ أَتَانِي مَلَكٌ فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنَّ رَبَّكَ يَقُولُ ‏ ‏أَمَا ‏ ‏يُرْضِيكَ أَنْ لَا يُصَلِّيَ عَلَيْكَ أَحَدٌ مِنْ أُمَّتِكَ إِلَّا صَلَّيْتُ عَلَيْهِ عَشْرًا وَلَا يُسَلِّمُ عَلَيْكَ إِلَّا سَلَّمْتُ عَلَيْهِ عَشْرًا ‏","","",""],[15768,15768,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ حَفْصٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَأُرَاهُ ذَكَرَهُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَوَضَّئُوا مِمَّا أَنْضَجَتْ النَّارُ ‏","","",""],[15769,15769,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏مَوْلَى ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ ذَاتَ يَوْمٍ وَالسُّرُورُ يُرَى فِي وَجْهِهِ فَقَالُوا يَا رَسُولَ اللَّهِ إِنَّا ‏ ‏لَنَرَى السُّرُورَ فِي وَجْهِكَ فَقَالَ إِنَّهُ أَتَانِي مَلَكٌ فَقَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏أَمَا ‏ ‏يُرْضِيكَ أَنَّ رَبَّكَ عَزَّ وَجَلَّ يَقُولُ ‏ ‏إِنَّهُ لَا ‏ ‏يُصَلِّي عَلَيْكَ أَحَدٌ مِنْ أُمَّتِكَ إِلَّا صَلَّيْتُ عَلَيْهِ عَشْرًا وَلَا يُسَلِّمُ عَلَيْكَ أَحَدٌ مِنْ أُمَّتِكَ إِلَّا سَلَّمْتُ عَلَيْهِ عَشْرًا قَالَ بَلَى ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏قَالَ ‏ ‏قَدِمَ عَلَيْنَا ‏ ‏سُلَيْمَانُ ‏ ‏مَوْلَى ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏زَمَنَ ‏ ‏الْحَجَّاجِ ‏ ‏فَحَدَّثَنَا عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَ ذَاتَ يَوْمٍ ‏ ‏وَالْبِشْرُ ‏ ‏يُرَى فِي وَجْهِهِ ‏ ‏فَذَكَرَهُ ‏","","",""],[15770,15770,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏مُوسَى بْنُ عُقْبَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنْتُ أَنَا ‏ ‏وَأُبَيُّ بْنُ كَعْبٍ ‏ ‏وَأَبُو طَلْحَةَ ‏ ‏جُلُوسًا فَأَكَلْنَا لَحْمًا وَخُبْزًا ثُمَّ دَعَوْتُ بِوَضُوءٍ ‏ ‏فَقَالَا ‏ ‏لِمَ تَتَوَضَّأُ فَقُلْتُ لِهَذَا الطَّعَامِ الَّذِي أَكَلْنَا فَقَالَا أَتَتَوَضَّأُ مِنْ الطَّيِّبَاتِ لَمْ يَتَوَضَّأْ مَنْ هُوَ خَيْرٌ مِنْكَ ‏","","",""],[15771,15771,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبُ بْنُ ثَابِتٍ ‏ ‏كَانَ يَسْكُنُ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏قَرَأَ رَجُلٌ عِنْدَ ‏ ‏عُمَرَ ‏ ‏فَغَيَّرَ عَلَيْهِ فَقَالَ قَرَأْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ يُغَيِّرْ عَلَيَّ قَالَ فَاجْتَمَعْنَا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَرَأَ الرَّجُلُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَهُ قَدْ أَحْسَنْتَ قَالَ فَكَأَنَّ ‏ ‏عُمَرَ ‏ ‏وَجَدَ ‏ ‏مِنْ ذَلِكَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عُمَرُ ‏ ‏إِنَّ الْقُرْآنَ كُلَّهُ صَوَابٌ مَا لَمْ يُجْعَلْ عَذَابٌ مَغْفِرَةً ‏ ‏أَوْ مَغْفِرَةٌ عَذَابًا ‏ ‏وَقَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏مَرَّةً أُخْرَى ‏ ‏أَبُو ثَابِتٍ ‏ ‏مِنْ كِتَابِهِ ‏","","",""],[15772,15772,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ حَكِيمٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ قَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏كُنَّا جُلُوسًا ‏ ‏بِالْأَفْنِيَةِ ‏ ‏فَمَرَّ بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا لَكُمْ وَلِمَجَالِسِ ‏ ‏الصُّعُدَاتِ ‏ ‏اجْتَنِبُوا مَجَالِسَ ‏ ‏الصُّعُدَاتِ ‏ ‏قَالَ قُلْنَا يَا رَسُولَ اللَّهِ إِنَّا جَلَسْنَا لِغَيْرِ مَا بَأْسٍ نَتَذَاكَرُ وَنَتَحَدَّثُ قَالَ ‏ ‏فَأَعْطُوا الْمَجَالِسَ حَقَّهَا قُلْنَا وَمَا حَقُّهَا قَالَ ‏ ‏غَضُّ ‏ ‏الْبَصَرِ وَرَدُّ السَّلَامِ وَحُسْنُ الْكَلَامِ ‏","","",""],[15773,15773,"","","‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ حَجَّاجٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏فَذَكَرَ حَدِيثًا قَالَ وَحَدَّثَنِي ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى بْنُ سُلَيْمِ بْنِ زَيْدٍ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏إِسْمَاعِيلَ بْنَ بَشِيرٍ ‏ ‏مَوْلَى ‏ ‏بَنِي مَغَالَةَ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏وَأَبَا طَلْحَةَ بْنَ سَهْلٍ ‏ ‏الْأَنْصَارِيَّيْنِ ‏ ‏يَقُولَانِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ امْرِئٍ ‏ ‏يَخْذُلُ ‏ ‏امْرَأً مُسْلِمًا عِنْدَ مَوْطِنٍ ‏ ‏تُنْتَهَكُ ‏ ‏فِيهِ حُرْمَتُهُ وَيُنْتَقَصُ فِيهِ مِنْ عِرْضِهِ إِلَّا ‏ ‏خَذَلَهُ ‏ ‏اللَّهُ عَزَّ وَجَلَّ فِي مَوْطِنٍ يُحِبُّ فِيهِ نُصْرَتَهُ وَمَا مِنْ امْرِئٍ يَنْصُرُ امْرَأً مُسْلِمًا فِي مَوْطِنٍ يُنْتَقَصُ فِيهِ مِنْ عِرْضِهِ وَيُنْتَهَكُ فِيهِ مِنْ حُرْمَتِهِ إِلَّا نَصَرَهُ اللَّهُ فِي مَوْطِنٍ يُحِبُّ فِيهِ نُصْرَتَهُ ‏","","",""],[15774,15774,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُهَيْلُ بْنُ أَبِي صَالِحٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ يَسَارٍ ‏ ‏عَنْ ‏ ‏أَبِي طَلْحَةَ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْمَلَائِكَةَ لَا تَدْخُلُ بَيْتًا فِيهِ كَلْبٌ وَلَا صُورَةٌ ‏","","",""],[15775,15775,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏زَكَرِيَّا بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏عَنْ ‏ ‏نَافِعِ بْنِ جُبَيْرِ بْنِ مُطْعِمٍ ‏ ‏عَنْ ‏ ‏أَبِي شُرَيْحٍ الْخُزَاعِيِّ ‏ ‏وَكَانَتْ لَهُ صُحْبَةٌ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُحْسِنْ إِلَى جَارِهِ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ ‏","","",""],[15776,15776,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي شُرَيْحٍ الْخُزَاعِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الضِّيَافَةُ ثَلَاثَةُ أَيَّامٍ ‏ ‏وَجَائِزَتُهُ ‏ ‏يَوْمٌ وَلَيْلَةٌ وَلَا يَحِلُّ لِلرَّجُلِ أَنْ يُقِيمَ عِنْدَ أَحَدٍ حَتَّى ‏ ‏يُؤْثِمَهُ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ فَكَيْفَ ‏ ‏يُؤْثِمُهُ ‏ ‏قَالَ يُقِيمُ عِنْدَهُ وَلَيْسَ لَهُ شَيْءٌ ‏ ‏يَقْرِيهِ ‏","","",""],[15777,15777,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْمَقْبُرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي شُرَيْحٍ الْكَعْبِيِّ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَاللَّهِ لَا يُؤْمِنُ وَاللَّهِ لَا يُؤْمِنُ وَاللَّهِ لَا يُؤْمِنُ قَالَهَا ثَلَاثَ مَرَّاتٍ قَالُوا وَمَا ذَاكَ يَا رَسُولَ اللَّهِ قَالَ الْجَارُ لَا يَأْمَنُ الْجَارُ ‏ ‏بَوَائِقَهُ ‏ ‏قَالُوا وَمَا ‏ ‏بَوَائِقُهُ ‏ ‏قَالَ شَرُّهُ ‏","","",""],[15778,15778,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدٌ يَعْنِي الْمَقْبُرِيَّ ‏ ‏عَنْ ‏ ‏أَبِي شُرَيْحٍ الْعَدَوِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِعَمْرِو بْنِ سَعِيدٍ ‏ ‏وَهُوَ يَبْعَثُ الْبُعُوثَ إِلَى ‏ ‏مَكَّةَ ‏ ‏ائْذَنْ لِي أَيُّهَا الْأَمِيرُ أُحَدِّثْكَ قَوْلًا قَامَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْغَدَ مِنْ يَوْمِ الْفَتْحِ سَمِعَتْهُ أُذُنَايَ وَوَعَاهُ قَلْبِي وَأَبْصَرَتْهُ عَيْنَايَ حِينَ تَكَلَّمَ بِهِ أَنْ حَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ ‏ ‏إِنَّ ‏ ‏مَكَّةَ ‏ ‏حَرَّمَهَا اللَّهُ وَلَمْ يُحَرِّمْهَا النَّاسُ فَلَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ يَسْفِكَ بِهَا دَمًا وَلَا ‏ ‏يَعْضِدَ ‏ ‏بِهَا شَجَرَةً فَإِنْ أَحَدٌ تَرَخَّصَ لِقِتَالِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا فَقُولُوا إِنَّ اللَّهَ عَزَّ وَجَلَّ أَذِنَ لِرَسُولِهِ وَلَمْ يَأْذَنْ لَكُمْ إِنَّمَا أَذِنَ لِي فِيهَا سَاعَةً مِنْ نَهَارٍ وَقَدْ عَادَتْ حُرْمَتُهَا الْيَوْمَ كَحُرْمَتِهَا بِالْأَمْسِ وَلْيُبَلِّغْ الشَّاهِدُ الْغَائِبَ ‏","","",""],[15779,15779,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي شُرَيْحٍ الْعَدَوِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏سَمِعَتْ أُذُنَايَ وَأَبْصَرَتْ عَيْنَايَ حِينَ تَكَلَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ جَارَهُ وَمَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيُكْرِمْ ضَيْفَهُ ‏ ‏جَائِزَتَهُ ‏ ‏قَالُوا وَمَا ‏ ‏جَائِزَتُهُ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ يَوْمٌ وَلَيْلَةٌ وَالضِّيَافَةُ ثَلَاثٌ فَمَا كَانَ وَرَاءَ ذَلِكَ فَهُوَ ‏ ‏صَدَقَةٌ ‏ ‏عَلَيْهِ وَقَالَ مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ ‏ ‏وَقَالَ ‏ ‏أَبُو كَامِلٍ ‏ ‏وَلَا ‏ ‏يَثْوِي ‏ ‏عِنْدَهُ حَتَّى ‏ ‏يُحْرِجَهُ ‏","","",""],[15780,15780,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ الْحَرَّانِيُّ ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْحَارِثِ بْنِ فُضَيْلٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ بْنِ أَبِي الْعَوْجَاءِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي شُرَيْحٍ الْخُزَاعِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أُصِيبَ بِدَمٍ أَوْ ‏ ‏خَبْلٍ ‏ ‏الْخَبْلُ ‏ ‏الْجِرَاحُ ‏ ‏فَهُوَ بِالْخِيَارِ بَيْنَ إِحْدَى ثَلَاثٍ إِمَّا أَنْ ‏ ‏يَقْتَصَّ ‏ ‏أَوْ يَأْخُذَ ‏ ‏الْعَقْلَ ‏ ‏أَوْ يَعْفُوَ فَإِنْ أَرَادَ رَابِعَةً فَخُذُوا عَلَى يَدَيْهِ فَإِنْ فَعَلَ شَيْئًا مِنْ ذَلِكَ ثُمَّ عَدَا بَعْدُ فَقَتَلَ فَلَهُ النَّارُ خَالِدًا فِيهَا مُخَلَّدًا ‏","","",""],[15781,15781,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏يُونُسَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ يَزِيدَ ‏ ‏أَحَدِ ‏ ‏بَنِي سَعْدِ بْنِ بَكْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا شُرَيْحٍ الْخُزَاعِيَّ ‏ ‏ثُمَّ ‏ ‏الْكَعْبِيَّ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَقُولُ ‏ ‏أَذِنَ لَنَا رَسُولُ اللَّهِ يَوْمَ الْفَتْحِ فِي قِتَالِ ‏ ‏بَنِي بَكْرٍ ‏ ‏حَتَّى أَصَبْنَا مِنْهُمْ ثَأْرَنَا وَهُوَ ‏ ‏بِمَكَّةَ ‏ ‏ثُمَّ أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَفْعِ السَّيْفِ فَلَقِيَ ‏ ‏رَهْطٌ ‏ ‏مِنَّا الْغَدَ رَجُلًا مِنْ ‏ ‏هُذَيْلٍ ‏ ‏فِي ‏ ‏الْحَرَمِ ‏ ‏يَؤُمُّ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُسْلِمَ وَكَانَ قَدْ ‏ ‏وَتَرَهُمْ ‏ ‏فِي الْجَاهِلِيَّةِ وَكَانُوا يَطْلُبُونَهُ فَقَتَلُوهُ وَبَادَرُوا أَنْ ‏ ‏يَخْلُصَ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَأْمَنَ فَلَمَّا بَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَضِبَ غَضَبًا شَدِيدًا وَاللَّهِ مَا رَأَيْتُهُ غَضِبَ غَضَبًا أَشَدَّ مِنْهُ فَسَعَيْنَا إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏نَسْتَشْفِعُهُمْ ‏ ‏وَخَشِينَا أَنْ نَكُونَ قَدْ هَلَكْنَا فَلَمَّا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فَأَثْنَى عَلَى اللَّهِ عَزَّ وَجَلَّ بِمَا هُوَ أَهْلُهُ ثُمَّ قَالَ أَمَّا بَعْدُ ‏ ‏فَإِنَّ اللَّهَ عَزَّ وَجَلَّ هُوَ حَرَّمَ ‏ ‏مَكَّةَ ‏ ‏وَلَمْ يُحَرِّمْهَا النَّاسُ وَإِنَّمَا أَحَلَّهَا لِي سَاعَةً مِنْ النَّهَارِ أَمْسِ وَهِيَ الْيَوْمَ حَرَامٌ كَمَا حَرَّمَهَا اللَّهُ عَزَّ وَجَلَّ أَوَّلَ مَرَّةٍ وَإِنَّ ‏ ‏أَعْتَى ‏ ‏النَّاسِ عَلَى اللَّهِ عَزَّ وَجَلَّ ثَلَاثَةٌ رَجُلٌ قَتَلَ فِيهَا وَرَجُلٌ قَتَلَ غَيْرَ قَاتِلِهِ وَرَجُلٌ طَلَبَ ‏ ‏بِذَحْلٍ ‏ ‏فِي الْجَاهِلِيَّةِ وَإِنِّي وَاللَّهِ لَأَدِيَنَّ هَذَا الرَّجُلَ الَّذِي قَتَلْتُمْ ‏ ‏فَوَدَاهُ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[15782,15782,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ أَبِي سَعِيدٍ الْمَقْبُرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي شُرَيْحٍ الْخُزَاعِيِّ ‏ ‏قَالَ ‏ ‏لَمَّا بَعَثَ ‏ ‏عَمْرُو بْنُ سَعِيدٍ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏بَعْثَهُ يَغْزُو ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏أَتَاهُ ‏ ‏أَبُو شُرَيْحٍ ‏ ‏فَكَلَّمَهُ وَأَخْبَرَهُ بِمَا سَمِعَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ خَرَجَ إِلَى نَادِي قَوْمِهِ فَجَلَسَ فِيهِ فَقُمْتُ إِلَيْهِ فَجَلَسْتُ مَعَهُ فَحَدَّثَ قَوْمَهُ كَمَا حَدَّثَ ‏ ‏عَمْرَو بْنَ سَعِيدٍ ‏ ‏مَا سَمِعَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَمَّا قَالَ لَهُ ‏ ‏عَمْرُو بْنُ سَعِيدٍ ‏ ‏قَالَ قُلْتُ هَذَا إِنَّا كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ افْتَتَحَ ‏ ‏مَكَّةَ ‏ ‏فَلَمَّا كَانَ الْغَدُ مِنْ يَوْمِ الْفَتْحِ ‏ ‏عَدَتْ ‏ ‏خُزَاعَةُ ‏ ‏عَلَى رَجُلٍ مِنْ ‏ ‏هُذَيْلٍ ‏ ‏فَقَتَلُوهُ وَهُوَ مُشْرِكٌ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِينَا خَطِيبًا فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ حَرَّمَ ‏ ‏مَكَّةَ ‏ ‏يَوْمَ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ فَهِيَ حَرَامٌ مِنْ حَرَامِ اللَّهِ تَعَالَى إِلَى يَوْمِ الْقِيَامَةِ لَا يَحِلُّ لِامْرِئٍ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَنْ ‏ ‏يَسْفِكَ ‏ ‏فِيهَا دَمًا وَلَا ‏ ‏يَعْضِدَ ‏ ‏بِهَا شَجَرًا لَمْ تَحْلِلْ لِأَحَدٍ كَانَ قَبْلِي وَلَا تَحِلُّ لِأَحَدٍ يَكُونُ بَعْدِي وَلَمْ تَحْلِلْ لِي إِلَّا هَذِهِ السَّاعَةَ غَضَبًا عَلَى أَهْلِهَا أَلَا ثُمَّ قَدْ رَجَعَتْ كَحُرْمَتِهَا بِالْأَمْسِ أَلَا فَلْيُبَلِّغْ الشَّاهِدُ مِنْكُمْ الْغَائِبَ فَمَنْ قَالَ لَكُمْ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ قَاتَلَ بِهَا فَقُولُوا إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ أَحَلَّهَا لِرَسُولِهِ وَلَمْ يُحْلِلْهَا لَكُمْ يَا مَعْشَرَ ‏ ‏خُزَاعَةَ ‏ ‏وَارْفَعُوا أَيْدِيَكُمْ عَنْ الْقَتْلِ فَقَدْ كَثُرَ أَنْ يَقَعَ لَئِنْ قَتَلْتُمْ قَتِيلًا ‏ ‏لَأَدِيَنَّهُ ‏ ‏فَمَنْ قُتِلَ بَعْدَ مَقَامِي هَذَا فَأَهْلُهُ بِخَيْرِ ‏ ‏النَّظَرَيْنِ ‏ ‏إِنْ شَاءُوا فَدَمُ قَاتِلِهِ وَإِنْ شَاءُوا ‏ ‏فَعَقْلُهُ ‏ ‏ثُمَّ ‏ ‏وَدَى ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّجُلَ الَّذِي قَتَلَتْهُ ‏ ‏خُزَاعَةُ ‏ ‏فَقَالَ ‏ ‏عَمْرُو بْنُ سَعِيدٍ ‏ ‏لِأَبِي شُرَيْحٍ ‏ ‏انْصَرِفْ أَيُّهَا الشَّيْخُ فَنَحْنُ أَعْلَمُ بِحُرْمَتِهَا مِنْكَ إِنَّهَا لَا تَمْنَعُ ‏ ‏سَافِكَ ‏ ‏دَمٍ وَلَا ‏ ‏خَالِعَ ‏ ‏طَاعَةٍ وَلَا مَانِعَ جِزْيَةٍ قَالَ فَقُلْتُ قَدْ كُنْتُ شَاهِدًا وَكُنْتَ غَائِبًا وَقَدْ بَلَّغْتُ وَقَدْ أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُبَلِّغَ شَاهِدُنَا غَائِبَنَا وَقَدْ بَلَّغْتُكَ فَأَنْتَ وَشَأْنُكَ ‏","","",""],[15783,15783,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏وَأَكْبَرُ عِلْمِي أَنَّ أَبِي ‏ ‏حَدَّثَنَا ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَزِيدَ اللَّيْثِيِّ ‏ ‏عَنْ ‏ ‏أَبِي شُرَيْحٍ الْخُزَاعِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ ‏ ‏أَعْتَى ‏ ‏النَّاسِ عَلَى اللَّهِ عَزَّ وَجَلَّ مَنْ قَتَلَ غَيْرَ قَاتِلِهِ أَوْ طَلَبَ بِدَمِ الْجَاهِلِيَّةِ مِنْ أَهْلِ الْإِسْلَامِ أَوْ بَصَّرَ عَيْنَيْهِ فِي النَّوْمِ مَا لَمْ ‏ ‏تُبْصِرَا ‏","","",""],[15784,15784,"","","‏ ‏حَدَّثَنَا ‏ ‏فَيَّاضُ بْنُ مُحَمَّدٍ الرَّقِّيُّ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ بُرْقَانَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الْحَجَّاجِ الْكِلَابِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْهَمْدَانِيِّ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ عُقْبَةَ ‏ ‏قَالَ ‏ ‏لَمَّا فَتَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَّةَ ‏ ‏جَعَلَ أَهْلُ ‏ ‏مَكَّةَ ‏ ‏يَأْتُونَهُ بِصِبْيَانِهِمْ ‏ ‏فَيَمْسَحُ عَلَى رُءُوسِهِمْ وَيَدْعُو لَهُمْ فَجِيءَ بِي إِلَيْهِ وَإِنِّي مُطَيَّبٌ ‏ ‏بِالْخَلُوقِ ‏ ‏وَلَمْ يَمْسَحْ عَلَى رَأْسِي وَلَمْ يَمْنَعْهُ مِنْ ذَلِكَ إِلَّا أَنَّ أُمِّي ‏ ‏خَلَّقَتْنِي ‏ ‏بِالْخَلُوقِ ‏ ‏فَلَمْ يَمَسَّنِي مِنْ أَجْلِ ‏ ‏الْخَلُوقِ ‏","","",""],[15785,15785,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ لَقِيطِ بْنِ صَبِرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَنْشَقْتَ فَبَالِغْ إِلَّا أَنْ تَكُونَ صَائِمًا ‏","","",""],[15786,15786,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ إِسْمَاعِيلَ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ لَقِيطِ بْنِ صَبِرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِذَا تَوَضَّأْتَ ‏ ‏فَخَلِّلْ ‏ ‏الْأَصَابِعَ ‏","","",""],[15787,15787,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ إِسْمَاعِيلَ بْنِ كَثِيرٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ لَقِيطِ بْنِ صَبِرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَبَحَ لَنَا شَاةً وَقَالَ ‏ ‏لَا تَحْسَبَنَّ وَلَمْ يَقُلْ لَا ‏ ‏يَحْسَبَنَّ ‏ ‏إِنَّا إِنَّمَا ذَبَحْنَاهَا لَكَ وَلَكِنْ لَنَا غَنَمٌ فَإِذَا بَلَغَتْ مِائَةً ذَبَحْنَا شَاةً ‏","","",""],[15788,15788,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ كَثِيرٍ أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ لَقِيطِ بْنِ صَبِرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَضَّأْتَ فَأَبْلِغْ فِي ‏ ‏الِاسْتِنْشَاقِ مَا لَمْ تَكُنْ صَائِمًا ‏","","",""],[15789,15789,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ كَثِيرٍ أَبُو هَاشِمٍ الْمَكِّيُّ ‏ ‏عَنْ ‏ ‏عَاصِمِ بْنِ لَقِيطِ بْنِ صَبِرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَافِدِ ‏ ‏بَنِي الْمُنْتَفِقِ ‏ ‏قَالَ ‏ ‏انْطَلَقْتُ أَنَا وَصَاحِبٌ لِي حَتَّى انْتَهَيْنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ نَجِدْهُ فَأَطْعَمَتْنَا ‏ ‏عَائِشَةُ ‏ ‏تَمْرًا ‏ ‏وَعَصَدَتْ ‏ ‏لَنَا ‏ ‏عَصِيدَةً ‏ ‏إِذْ جَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَقَلَّعُ ‏ ‏فَقَالَ هَلْ أُطْعِمْتُمْ مِنْ شَيْءٍ قُلْنَا نَعَمْ يَا رَسُولَ اللَّهِ فَبَيْنَا نَحْنُ كَذَلِكَ ‏ ‏دَفَعَ ‏ ‏رَاعِي الْغَنَمِ فِي ‏ ‏الْمُرَاحِ ‏ ‏عَلَى يَدِهِ ‏ ‏سَخْلَةٌ ‏ ‏قَالَ هَلْ وَلَدَتْ قَالَ نَعَمْ قَالَ فَاذْبَحْ لَنَا شَاةً ثُمَّ أَقْبِلْ عَلَيْنَا فَقَالَ ‏ ‏لَا تَحْسَبَنَّ وَلَمْ يَقُلْ لَا يَحْسَبَنَّ إِنَّا ذَبَحْنَا الشَّاةَ مِنْ أَجْلِكُمَا لَنَا غَنَمٌ مِائَةٌ لَا نُرِيدُ أَنْ تَزِيدَ عَلَيْهَا فَإِذَا وَلَّدَ الرَّاعِي ‏ ‏بَهْمَةً ‏ ‏أَمَرْنَاهُ بِذَبْحِ شَاةٍ فَقَالَ يَا رَسُولَ اللَّهِ أَخْبِرْنِي عَنْ الْوُضُوءِ قَالَ إِذَا تَوَضَّأْتَ ‏ ‏فَأَسْبِغْ ‏ ‏وَخَلِّلْ ‏ ‏الْأَصَابِعَ وَإِذَا اسْتَنْثَرْتَ فَأَبْلِغْ إِلَّا أَنْ تَكُونَ صَائِمًا قَالَ يَا رَسُولَ اللَّهِ إِنَّ لِي امْرَأَةً فَذَكَرَ مِنْ طُولِ لِسَانِهَا وَإِيذَائِهَا فَقَالَ طَلِّقْهَا قَالَ يَا رَسُولَ اللَّهِ إِنَّهَا ذَاتُ صُحْبَةٍ وَوَلَدٍ قَالَ فَأَمْسِكْهَا وَأْمُرْهَا فَإِنْ يَكُ فِيهَا خَيْرٌ فَسَتَفْعَلْ وَلَا تَضْرِبْ ‏ ‏ظَعِينَتَكَ ‏ ‏ضَرْبَكَ أَمَتَكَ ‏","","",""],[15790,15790,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الضَّحَّاكِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَعْنُ ‏ ‏الْمُؤْمِنِ كَقَتْلِهِ وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ فِي الدُّنْيَا عُذِّبَ بِهِ فِي الْآخِرَةِ وَلَيْسَ عَلَى رَجُلٍ مُسْلِمٍ ‏ ‏نَذْرٌ ‏ ‏فِيمَا لَا يَمْلِكُ وَمَنْ رَمَى مُؤْمِنًا بِكُفْرٍ فَهُوَ كَقَتْلِهِ وَمَنْ حَلَفَ ‏ ‏بِمِلَّةٍ ‏ ‏سِوَى الْإِسْلَامِ كَاذِبًا فَهُوَ كَمَا قَالَ ‏","","",""],[15791,15791,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الضَّحَّاكِ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ ‏ ‏بِمِلَّةٍ ‏ ‏سِوَى الْإِسْلَامِ كَاذِبًا مُتَعَمِّدًا فَهُوَ كَمَا قَالَ ‏","","",""],[15792,15792,"","","‏ ‏وَقَالَ ‏ ‏مَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ عَذَّبَهُ اللَّهُ بِهِ فِي نَارِ جَهَنَّمَ ‏","","",""],[15793,15793,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو قِلَابَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ثَابِتُ بْنُ الضَّحَّاكِ الْأَنْصَارِيِّ ‏ ‏وَكَانَ مِمَّنْ بَايَعَ تَحْتَ الشَّجَرَةِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ عَلَى يَمِينٍ ‏ ‏بِمِلَّةٍ ‏ ‏سِوَى الْإِسْلَامِ كَاذِبًا فَهُوَ كَمَا قَالَ وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ عُذِّبَ بِهِ يَوْمَ الْقِيَامَةِ وَلَيْسَ عَلَى رَجُلٍ ‏ ‏نَذْرٌ ‏ ‏فِيمَا لَا يَمْلِكُ ‏","","",""],[15794,15794,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ الشَّيْبَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ السَّائِبِ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مَعْقِلٍ ‏ ‏عَنْ ‏ ‏الْمُزَارَعَةِ ‏ ‏فَقَالَ حَدَّثَنَا ‏ ‏ثَابِتُ بْنُ الضَّحَّاكِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْمُزَارَعَةِ ‏","","",""],[15795,15795,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الضَّحَّاكِ الْأَنْصَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ حَلَفَ عَلَى ‏ ‏مِلَّةٍ ‏ ‏سِوَى الْإِسْلَامِ كَاذِبًا فَهُوَ كَمَا قَالَ وَلَيْسَ عَلَى رَجُلٍ ‏ ‏نَذْرٌ ‏ ‏فِيمَا لَا يَمْلِكُ وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ فِي الدُّنْيَا عُذِّبَ بِهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[15796,15796,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الضَّحَّاكِ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ الشَّجَرَةِ ‏ ‏ثُمَّ قَالَ ‏ ‏بَعْدُ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الضَّحَّاكِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ حَلَفَ ‏ ‏بِمِلَّةٍ ‏ ‏سِوَى الْإِسْلَامِ كَاذِبًا مُتَعَمِّدًا فَهُوَ كَمَا قَالَ وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ أَوْ ذَبَحَ ذَبَحَهُ اللَّهُ بِهِ فِي نَارِ جَهَنَّمَ ‏","","",""],[15797,15797,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الضَّحَّاكِ ‏ ‏رَفَعَ الْحَدِيثَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ عُذِّبَ بِهِ وَمَنْ شَهِدَ عَلَى مُسْلِمٍ ‏ ‏أَوْ قَالَ مُؤْمِنٍ ‏ ‏بِكُفْرٍ فَهُوَ كَقَتْلِهِ وَمَنْ ‏ ‏لَعَنَهُ ‏ ‏فَهُوَ كَقَتْلِهِ وَمَنْ حَلَفَ عَلَى ‏ ‏مِلَّةٍ ‏ ‏غَيْرِ الْإِسْلَامِ كَاذِبًا فَهُوَ كَمَا حَلَفَ ‏","","",""],[15798,15798,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ الضَّحَّاكِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَلَفَ ‏ ‏بِمِلَّةٍ ‏ ‏سِوَى الْإِسْلَامِ كَاذِبًا مُتَعَمِّدًا فَهُوَ كَمَا قَالَ وَمَنْ قَتَلَ نَفْسَهُ بِشَيْءٍ عَذَّبَهُ اللَّهُ فِي نَارِ جَهَنَّمَ ‏","","",""],[15799,15799,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ أَسْلَمَ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ مِحْجَنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏وَعَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ مِحْجَنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأُقِيمَتْ الصَّلَاةُ فَجَلَسْتُ فَلَمَّا صَلَّى قَالَ لِي أَلَسْتَ بِمُسْلِمٍ قُلْتُ بَلَى قَالَ فَمَا مَنَعَكَ أَنْ تُصَلِّيَ مَعَ النَّاسِ قَالَ قُلْتُ صَلَّيْتُ فِي أَهْلِي قَالَ ‏ ‏فَصَلِّ مَعَ النَّاسِ وَلَوْ كُنْتَ قَدْ صَلَّيْتَ فِي أَهْلِكَ ‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ مِحْجَنٍ الدِّيلِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ صَلَّيْتُ فِي أَهْلِي فَأُقِيمَتْ الصَّلَاةُ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏","","",""],[15800,15800,"","","‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي الدِّيلِ ‏ ‏يُقَالُ لَهُ ‏ ‏بُسْرُ بْنُ مِحْجَنٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏مِحْجَنٍ ‏ ‏أَنَّهُ كَانَ فِي مَجْلِسٍ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأُذِّنَ بِالصَّلَاةِ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى ثُمَّ رَجَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمِحْجَنٌ ‏ ‏فِي مَجْلِسِهِ فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مَنَعَكَ أَنْ تُصَلِّيَ مَعَ النَّاسِ أَلَسْتَ بِرَجُلٍ مُسْلِمٍ قَالَ بَلَى يَا رَسُولَ اللَّهِ وَلَكِنِّي كُنْتُ قَدْ صَلَّيْتُ فِي أَهْلِي فَقَالَ لَهُ إِذَا ‏ ‏جِئْتَ فَصَلِّ مَعَ النَّاسِ وَإِنْ كُنْتَ قَدْ صَلَّيْتَ ‏","","",""]];
